"use client";

// Atualização de publicação: perfil administrativo.
import {
  Bell,
  CalendarDays,
  ChevronDown,
  CircleHelp,
  ClipboardCheck,
  FileText,
  Landmark,
  MessageCircle,
  LayoutDashboard,
  MapPinned,
  MoreVertical,
  Plus,
  Settings,
  Users,
  WalletCards,
  X,
} from "lucide-react";
import { useEffect, useState } from "react";
import financeStyles from "./finance.module.css";
import { assignReservationToRoom, createClient, createContactLog, createDepartureCost, createRoomGroup, deleteClientWithReservations, deleteReservation, getSession, listClients, listContactLogs, listDepartureCosts, listDepartures, listPayments, listReservations, listRoomGroups, markPaymentAsPaid, replacePendingPaymentPlan, signOut, supabaseConfigured, updateClient, updateDepartureCapacity, updateDepartureCostActual, updateDepartureCostSettings, getMyProfile, updateMyProfile, uploadProfilePhoto, type ClientRecord, type ContactLogRecord, type DepartureCostRecord, type DepartureRecord, type PaymentRecord, type ReservationRecord, type RoomGroupRecord, type TeamMemberRecord } from "../../lib/supabase-browser";

void financeStyles;

const navItems = [
  [LayoutDashboard, "Início"], [MapPinned, "Saídas"], [Users, "Clientes"], [WalletCards, "Financeiro"],
  [ClipboardCheck, "Operações"], [FileText, "Documentos"], [MessageCircle, "Comunicação"], [Landmark, "Relatórios"],
] as const;

const modules = {
  "Início": { eyebrow: "Visão do dia", title: "A jornada da equipe", summary: "Acompanhe a operação a partir das inscrições reais recebidas.", cards: [] },
  "Saídas": { eyebrow: "Saídas", title: "Andes Essencial", summary: "Acompanhamento das inscrições, preparação e financeiro reais.", cards: [] },
  "Clientes": { eyebrow: "Relacionamento", title: "Clientes e viajantes", summary: "Cadastros, contatos e documentos em uma única ficha.", cards: [] },
  "Financeiro": { eyebrow: "Fluxo financeiro", title: "Pagamentos com clareza", summary: "Entradas e parcelas registradas nas inscrições reais.", cards: [] },
  "Operações": { eyebrow: "Bastidores da viagem", title: "Operação", summary: "Organize os detalhes à medida que o grupo for formado.", cards: [] },
  "Documentos": { eyebrow: "Conferência", title: "Documentos", summary: "Passaportes e informações de saúde serão organizados por inscrição.", cards: [] },
  "Comunicação": { eyebrow: "WhatsApp e relacionamento", title: "Comunicação", summary: "Use roteiros de mensagem vinculados a dados reais.", cards: [] },
  "Relatórios": { eyebrow: "Leitura do negócio", title: "Relatórios", summary: "Acompanhe ocupação e receita quando as inscrições começarem.", cards: [] },
} as const;

function Status({ children, tone = "ok" }: { children: React.ReactNode; tone?: "ok" | "warn" | "neutral" }) {
  return <span className={`management-status ${tone}`}>{children}</span>;
}

export default function ManagementPage() {
  const [activeTab, setActiveTab] = useState("Participantes");
  const [activeModule, setActiveModule] = useState<keyof typeof modules>("Saídas");
  const [notice, setNotice] = useState<string | null>(null);
  const [checkingAccess, setCheckingAccess] = useState(true);
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [profile, setProfile] = useState<TeamMemberRecord | null>(null);
  const [profileOpen, setProfileOpen] = useState(false);
  const [profileName, setProfileName] = useState("");
  const [profilePhoto, setProfilePhoto] = useState<File | null>(null);
  const [profileSaving, setProfileSaving] = useState(false);
  const [clients, setClients] = useState<ClientRecord[]>([]);
  const [clientsLoading, setClientsLoading] = useState(false);
  const [payments, setPayments] = useState<PaymentRecord[]>([]);
  const [reservations, setReservations] = useState<ReservationRecord[]>([]);
  const [departures, setDepartures] = useState<DepartureRecord[]>([]);
  const [selectedDepartureId, setSelectedDepartureId] = useState<string | null>(null);
  const [roomGroups, setRoomGroups] = useState<RoomGroupRecord[]>([]);
  const [contactLogs, setContactLogs] = useState<ContactLogRecord[]>([]);
  const [departureCosts, setDepartureCosts] = useState<DepartureCostRecord[]>([]);

  useEffect(() => {
    if (!supabaseConfigured) { setCheckingAccess(false); return; }
    const session = getSession();
    if (!session) { window.location.replace("/gestao/login"); return; }
    setUserEmail(session.user.email ?? null);
    setCheckingAccess(false);
  }, []);

  useEffect(() => {
    if (!(["Saídas", "Clientes", "Documentos", "Comunicação", "Relatórios"].includes(activeModule)) || !supabaseConfigured) return;
    setClientsLoading(true);
    listClients().then(setClients).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar os clientes.")).finally(() => setClientsLoading(false));
  }, [activeModule]);
  useEffect(() => { if (["Saídas", "Financeiro", "Relatórios"].includes(activeModule) && supabaseConfigured) listPayments().then(setPayments).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar pagamentos.")); }, [activeModule]);
  useEffect(() => { if (activeModule === "Saídas" && supabaseConfigured) listReservations().then(setReservations).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar as reservas.")); }, [activeModule]);
  useEffect(() => { if (["Saídas", "Financeiro", "Operações", "Comunicação"].includes(activeModule) && supabaseConfigured) listDepartures().then((items) => { setDepartures(items); setSelectedDepartureId((current) => current && items.some((item) => item.id === current) ? current : items[0]?.id ?? null); }).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar as saídas.")); }, [activeModule]);
  useEffect(() => { if (activeModule === "Saídas" && selectedDepartureId) listRoomGroups(selectedDepartureId).then(setRoomGroups).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar os quartos.")); }, [activeModule, selectedDepartureId]);
  useEffect(() => { if (activeModule === "Comunicação" && supabaseConfigured) listContactLogs().then(setContactLogs).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar o histórico de contatos.")); }, [activeModule]);
  useEffect(() => { if (activeModule === "Operações" && selectedDepartureId && supabaseConfigured) listDepartureCosts(selectedDepartureId).then(setDepartureCosts).catch((error) => showNotice(error instanceof Error ? error.message : "Não foi possível carregar os custos deste roteiro.")); }, [activeModule, selectedDepartureId]);

  const selectedDeparture = departures.find((item) => item.id === selectedDepartureId) ?? null;
  const selectedReservations = selectedDeparture ? reservations.filter((item) => item.departure_id === selectedDeparture.id) : [];
  const selectedClientIds = new Set(selectedReservations.map((item) => item.clients?.id).filter(Boolean));
  const selectedClients = selectedDeparture ? clients.filter((item) => selectedClientIds.has(item.id)) : [];
  const selectedPayments = selectedDeparture ? payments.filter((item) => item.reservations?.departure_id === selectedDeparture.id) : [];
  const totalPlanned = selectedPayments.reduce((sum, item) => sum + item.amount_cents, 0);
  const totalReceived = selectedPayments.filter((item) => item.status === "pago").reduce((sum, item) => sum + item.amount_cents, 0);
  const money = (value: number) => new Intl.NumberFormat(selectedDeparture?.currency === "BRL" ? "pt-BR" : "en-US", { style: "currency", currency: selectedDeparture?.currency ?? "USD" }).format(value / 100);
  const formatDate = (date: string) => new Date(`${date}T12:00:00`).toLocaleDateString("pt-BR", { day: "2-digit", month: "short", year: "numeric" });
  const registrationUrl = selectedDeparture?.trips?.slug === "andes-essencial" ? "/inscricao" : `/inscricao/${selectedDeparture?.trips?.slug ?? ""}`;

  const fallbackName = userEmail?.toLowerCase() === "fabiano@ekonovaadv.com.br" ? "Fabiano Pellenz" : userEmail?.toLowerCase() === "cristiane@ekonovaadv.com.br" ? "Cristiane Pellenz" : (userEmail?.split("@")[0] ?? "Equipe Ekonova").replace(/(^|[._-])([a-z])/g, (_match, prefix, letter) => `${prefix === "." || prefix === "_" || prefix === "-" ? " " : ""}${letter.toUpperCase()}`);
  const currentUser = { name: profile?.full_name || fallbackName, initials: (profile?.full_name || fallbackName).split(" ").map((part) => part[0]).slice(0, 2).join("").toUpperCase(), avatarUrl: profile?.avatar_url ?? null };

  async function saveProfile(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const fullName = profileName.trim();
    if (!fullName) { showNotice("Informe seu nome para salvar o perfil."); return; }
    setProfileSaving(true);
    try {
      const avatarUrl = profilePhoto ? await uploadProfilePhoto(profilePhoto) : profile?.avatar_url ?? null;
      const updated = await updateMyProfile({ full_name: fullName, avatar_url: avatarUrl });
      setProfile(updated); setProfilePhoto(null); setProfileOpen(false);
      showNotice("Perfil atualizado.");
    } catch (error) {
      showNotice(error instanceof Error ? error.message : "Não foi possível salvar o perfil.");
    } finally { setProfileSaving(false); }
  }

  function showNotice(message: string) {
    setNotice(message);
    window.setTimeout(() => setNotice(null), 3400);
  }

  async function removeParticipant(reservation: ReservationRecord) {
    const name = reservation.clients?.full_name ?? "este viajante";
    const proceed = window.confirm(`Você está prestes a excluir a inscrição de ${name} desta saída. Os pagamentos e a alocação de quarto vinculados também serão removidos. Deseja continuar?`);
    if (!proceed) return;
    const confirmed = window.confirm(`Confirmação final: excluir definitivamente a inscrição de ${name}? Esta ação não poderá ser desfeita.`);
    if (!confirmed) return;
    try {
      await deleteReservation(reservation.id);
      const [nextReservations, nextPayments] = await Promise.all([listReservations(), listPayments()]);
      setReservations(nextReservations);
      setPayments(nextPayments);
      if (selectedDeparture) setRoomGroups(await listRoomGroups(selectedDeparture.id));
      showNotice("Inscrição excluída desta saída.");
    } catch (error) {
      showNotice(error instanceof Error ? error.message : "Não foi possível excluir a inscrição.");
    }
  }

  if (checkingAccess) return <main className="management-loading">Verificando acesso seguro…</main>;
  return (
    <main className="management-shell">
      <aside className="management-sidebar" aria-label="Navegação da gestão">
        <a className="management-brand" href="/">
          <span>Ekonova</span> Gestão
          <small>Viagens que transformam</small>
        </a>
        <nav>
          {navItems.map(([Icon, label]) => <button className={activeModule === label ? "active" : ""} key={label} onClick={() => setActiveModule(label as keyof typeof modules)}><Icon aria-hidden="true" />{label}</button>)}
        </nav>
        <div className="management-side-bottom">
          <button onClick={() => showNotice("Configurações: em breve.")}><Settings aria-hidden="true" />Configurações</button>
          <button onClick={() => showNotice("Central de ajuda: em breve.")}><CircleHelp aria-hidden="true" />Ajuda</button>
          <p>Mais natureza.<br />Melhores pessoas.</p>
        </div>
      </aside>

      <section className="management-content">
        <header className="management-topbar">
          <label><span className="sr-only">Buscar</span><input placeholder="Buscar saídas, clientes, reservas..." /></label>
          <button className="icon-button" aria-label="Notificações" onClick={() => showNotice("Você tem 3 pendências para hoje.")}><Bell aria-hidden="true" /><i /></button>
          <button className="current-user" onClick={() => { setProfileName(currentUser.name); setProfilePhoto(null); setProfileOpen(true); }} title="Editar meu perfil"><span>{currentUser.avatarUrl ? <img src={currentUser.avatarUrl} alt="" /> : currentUser.initials}</span><p><strong>{currentUser.name}</strong><small>{userEmail ?? "Ambiente de demonstração"}</small></p><ChevronDown aria-hidden="true" /></button>
        </header>

<>{profileOpen && <div className="profile-backdrop" role="presentation"><section className="profile-dialog" role="dialog" aria-modal="true" aria-labelledby="profile-title"><button className="profile-close" onClick={() => setProfileOpen(false)} aria-label="Fechar">×</button><p className="module-eyebrow">Meu perfil</p><h2 id="profile-title">Seus dados na gestão</h2><p>Atualize como a equipe identifica você no sistema.</p><form onSubmit={saveProfile}><label className="profile-photo-picker"><span>{currentUser.avatarUrl ? <img src={currentUser.avatarUrl} alt="" /> : currentUser.initials}</span><b>{profilePhoto ? "Nova foto selecionada" : "Escolher foto"}</b><input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setProfilePhoto(event.target.files?.[0] ?? null)} /></label><label>Nome completo<input value={profileName} onChange={(event) => setProfileName(event.target.value)} required /></label><label>E-mail<input value={userEmail ?? ""} readOnly /></label><div className="profile-actions"><button type="button" onClick={() => { signOut(); window.location.assign("/gestao/login"); }}>Sair da gestão</button><button type="submit" disabled={profileSaving}>{profileSaving ? "Salvando…" : "Salvar perfil"}</button></div></form></section></div>}</>
        <div className="management-page">
          {activeModule === "Clientes" ? <ClientsModule clients={clients} loading={clientsLoading} onAction={showNotice} onDeleted={async () => { const [nextClients, nextReservations, nextPayments] = await Promise.all([listClients(), listReservations(), listPayments()]); setClients(nextClients); setReservations(nextReservations); setPayments(nextPayments); }} /> : activeModule === "Documentos" ? <DocumentsModule clients={clients} loading={clientsLoading} /> : activeModule === "Financeiro" ? <FinanceModule payments={payments} departures={departures} onAction={showNotice} onUpdated={async () => setPayments(await listPayments())} /> : activeModule === "Operações" ? <OperationsModule departures={departures} selectedDepartureId={selectedDepartureId} onSelectDeparture={setSelectedDepartureId} costs={departureCosts} onAction={showNotice} onUpdated={async (departureId) => setDepartureCosts(await listDepartureCosts(departureId))} onSettingsUpdated={async () => setDepartures(await listDepartures())} /> : activeModule === "Relatórios" ? <ReportsModule clients={clients} payments={payments} /> : activeModule === "Comunicação" ? <CommunicationModule clients={clients} logs={contactLogs} departures={departures} onAction={showNotice} onLogged={async () => setContactLogs(await listContactLogs())} /> : activeModule !== "Saídas" ? <ModulePage module={modules[activeModule]} onAction={showNotice} /> : <>
          <section className="departure-catalog" aria-label="Saídas cadastradas"><div><p className="module-eyebrow">SAÍDAS OPERACIONAIS</p><h2>Escolha uma saída para gerir</h2><p>Inscrições, reservas, pagamentos e acomodação ficam separados por roteiro.</p></div><div className="departure-cards">{departures.map((departure) => <button key={departure.id} className={selectedDeparture?.id === departure.id ? "selected" : ""} onClick={() => setSelectedDepartureId(departure.id)}><small>{departure.trips?.category ?? "Roteiro"} · {departure.currency}</small><strong>{departure.trips?.title ?? "Saída"}</strong><span>{formatDate(departure.starts_on)} · {departure.capacity} vagas</span><em>{departure.public_registration_enabled ? "Inscrições abertas" : "Em preparação"}</em></button>)}</div>{!departures.length && <div className="empty-records"><strong>Nenhuma saída cadastrada ainda.</strong><p>As saídas operacionais aparecerão aqui assim que forem criadas.</p></div>}</section>
          {selectedDeparture && <>
          <button className="back-link" onClick={() => window.history.back()}>← Voltar para saídas</button>
          <section className="management-title-row">
            <div>
              <div className="title-line"><h1>{selectedDeparture.trips?.title ?? "Saída"}</h1><Status tone="neutral">● {selectedDeparture.public_registration_enabled ? "Inscrições abertas" : "Em preparação"}</Status></div>
              <p className="trip-subtitle">{selectedDeparture.trips?.category ?? "Roteiro"} <b /> {selectedDeparture.trips?.destination ?? "Destino a definir"}</p>
              <div className="trip-meta"><span><CalendarDays aria-hidden="true" />{formatDate(selectedDeparture.starts_on)} – {formatDate(selectedDeparture.ends_on)}</span><span><MapPinned aria-hidden="true" />{selectedDeparture.trips?.destination ?? "Destino"}</span><span><Users aria-hidden="true" />{selectedClients.length}/{selectedDeparture.capacity} inscrições</span></div>
            </div>
            <div className="title-actions">{selectedDeparture.public_registration_enabled ? <a href={registrationUrl} target="_blank" rel="noreferrer">Abrir link de inscrição</a> : <span>Link será liberado ao publicar a página do roteiro.</span>}</div>
          </section>

          <div className="management-layout">
            <section className="management-main-column">
              <div className="management-tabs" role="tablist" aria-label="Seções da saída">
                {["Participantes", "Rooming list", "Roteiro", "Operações", "Financeiro", "Documentos", "Comunicação"].map((tab) => <button role="tab" aria-selected={activeTab === tab} className={activeTab === tab ? "selected" : ""} key={tab} onClick={() => setActiveTab(tab)}>{tab}</button>)}
              </div>

              {activeTab === "Rooming list" ? <RoomingListModule reservations={selectedReservations} groups={roomGroups} onChange={async () => { if (selectedDeparture) setRoomGroups(await listRoomGroups(selectedDeparture.id)); }} onNotice={showNotice} /> : activeTab === "Financeiro" ? <FinanceModule payments={selectedPayments} departures={[selectedDeparture]} onAction={showNotice} onUpdated={async () => setPayments(await listPayments())} /> : activeTab === "Documentos" ? <ContractDocumentsModule departure={selectedDeparture} reservations={selectedReservations} payments={selectedPayments} /> : activeTab === "Participantes" ? <>
                <section className="participants-panel">
                  <div className="panel-heading"><h2>Inscrições recebidas <small>({selectedClients.length} de {selectedDeparture.capacity} vagas)</small></h2>{selectedDeparture.public_registration_enabled && <a className="panel-link" href={registrationUrl} target="_blank" rel="noreferrer"><Plus aria-hidden="true" />Abrir inscrição</a>}</div>
                  {selectedClients.length === 0 ? <div className="empty-records"><strong>Nenhuma inscrição recebida ainda.</strong><p>{selectedDeparture.public_registration_enabled ? "Compartilhe o link de inscrição para começar a formar o grupo." : "Esta saída está em preparação. O link será habilitado junto à página pública do roteiro."}</p></div> : <div className="participant-table" role="table">
                    <div className="participant-head" role="row"><span>Pessoa</span><span>Documentos</span><span>Pagamento</span><span>Preparação</span></div>
                    {selectedClients.map((client) => { const clientPayments = selectedPayments.filter((item) => item.reservations?.clients?.id === client.id); const reservation = selectedReservations.find((item) => item.clients?.id === client.id); const paid = clientPayments.every((item) => item.status === "pago") && clientPayments.length > 0; return <article className="participant-row" role="row" key={client.id}>
                      <div className="participant-row-main"><div className="person"><span className="client-initials">{client.full_name.split(" ").map((part) => part[0]).slice(0, 2).join("")}</span><p><strong>{client.full_name}</strong><small>{client.city ?? "Cidade não informada"}</small></p></div>
                      <div><Status tone={client.passport_number ? "ok" : "warn"}>{client.passport_number ? "● Informado" : "● Pendente"}</Status><small>{client.passport_number ? "Passaporte cadastrado" : "Aguardando documentos"}</small></div>
                      <div><Status tone={paid ? "ok" : "warn"}>{paid ? "● Pago" : "● Em aberto"}</Status><small>{clientPayments.length ? `${clientPayments.length} lançamento(s)` : "Sem lançamentos"}</small></div>
                      <div><Status tone={client.emergency_contact_name && client.health_plan ? "ok" : "warn"}>{client.emergency_contact_name && client.health_plan ? "● Completa" : "● Em andamento"}</Status><small>{client.emergency_contact_name && client.health_plan ? "Ficha operacional pronta" : "Completar ficha"}</small></div></div>
                      {reservation && <div className="participant-row-actions"><details><summary>Opções da inscrição</summary><button className="destructive-link" onClick={() => removeParticipant(reservation)}>Excluir inscrição</button></details></div>}
                    </article>; })}
                  </div>}
                </section>

                <section className="checklist-panel">
                  <div className="panel-heading"><h2>Próximos passos</h2></div>
                  <div className="empty-records"><strong>A operação será preparada após as primeiras inscrições.</strong><p>Documentos, rooming list, pagamentos e comunicação serão organizados a partir dos cadastros reais.</p></div>
                </section>
              </> : <section className="empty-section"><h2>{activeTab}</h2><p>Esta seção está pronta para receber os dados da operação.</p><button onClick={() => setActiveTab("Participantes")}>Voltar aos participantes</button></section>}
            </section>

            <aside className="trip-summary">
              <h2>Ritmo da saída</h2><p>Dados reais de ocupação e financeiro</p>
              <div className="occupancy"><div className="occupancy-ring"><strong>{selectedClients.length}/{selectedDeparture.capacity}</strong></div><div><b>Inscrições recebidas</b><strong>{selectedClients.length} de {selectedDeparture.capacity} vagas</strong><small>{Math.max(selectedDeparture.capacity - selectedClients.length, 0)} vaga(s) disponível(is)</small></div></div>
              <div className="summary-block"><span>Total previsto</span><div><strong>{money(totalPlanned)}</strong><small>Recebido: {money(totalReceived)}</small></div><i><b style={{ width: totalPlanned ? `${Math.round((totalReceived / totalPlanned) * 100)}%` : "0%" }} /></i><em>{totalPlanned ? `${Math.round((totalReceived / totalPlanned) * 100)}%` : "0%"}</em></div>
              <div className="payments-list"><div className="section-label"><b>Próximos pagamentos</b></div>{selectedPayments.filter((item) => item.status !== "pago").slice(0, 3).map((item) => <article key={item.id}><i /><p>{item.reservations?.clients?.full_name ?? "Cliente"}</p><strong>{money(item.amount_cents)}<small>até {new Date(`${item.due_on}T12:00:00`).toLocaleDateString("pt-BR")}</small></strong></article>)}{selectedPayments.length === 0 && <p className="empty-payments">Nenhum lançamento financeiro registrado.</p>}</div>
              {selectedDeparture.public_registration_enabled ? <a className="charge-button" href={registrationUrl} target="_blank" rel="noreferrer"><Users aria-hidden="true" />Compartilhar inscrição</a> : <span className="disabled-link">Inscrições aguardando página pública</span>}
              <div className="trip-reminders"><h3>Próximo passo</h3><p>Envie o link de inscrição para os viajantes. A preparação será organizada conforme os cadastros reais entrarem.</p></div>
            </aside>
          </div></>}</>}
        </div>
      </section>
      {!supabaseConfigured && <div className="management-demo-note">Modo de demonstração — conecte o Supabase para ativar acesso e dados reais.</div>}
      {notice && <div className="management-toast" role="status">{notice}<button aria-label="Fechar" onClick={() => setNotice(null)}><X aria-hidden="true" /></button></div>}
    </main>
  );
}

function ModulePage({ module, onAction }: { module: typeof modules[keyof typeof modules]; onAction: (message: string) => void }) {
  return <section className="module-page"><p className="module-eyebrow">{module.eyebrow}</p><h1>{module.title}</h1><p className="module-summary">{module.summary}</p><section className="module-workspace"><div><h2>Aguardando dados reais</h2><p>Esta área será preenchida conforme chegarem inscrições, contatos e registros da equipe.</p></div><a href="/inscricao" target="_blank" rel="noreferrer">Abrir inscrição do Andes</a></section></section>;
}

function RoomingListModule({ reservations, groups, onChange, onNotice }: { reservations: ReservationRecord[]; groups: RoomGroupRecord[]; onChange: () => Promise<void>; onNotice: (message: string) => void }) {
  const [roomLabel, setRoomLabel] = useState("");
  const [roomType, setRoomType] = useState<RoomGroupRecord["room_type"]>("twin");
  const csvCell = (value: string | null | undefined) => `"${(value ?? "").replaceAll('"', '""')}"`;
  function exportCsv() {
    const header = ["Nome completo", "Quarto", "Tipo de quarto", "E-mail", "Telefone", "Cidade", "CPF", "RG", "Passaporte", "Contato de segurança", "Telefone de segurança", "Plano de saúde / seguro", "Telefone do plano", "Pagamento"];
    const rows = reservations.map((reservation) => { const client = reservation.clients; const group = groups.find((item) => item.room_group_members.some((member) => member.reservation_id === reservation.id)); return [client?.full_name, group?.label ?? "Não alocado", group?.room_type ?? "", client?.email, client?.phone, [client?.city, client?.state].filter(Boolean).join(" - "), client?.cpf, client?.rg, client?.passport_number, client?.emergency_contact_name, client?.emergency_contact_phone, client?.health_plan, client?.health_plan_phone, reservation.payment_plan].map(csvCell).join(";"); });
    const csv = [header.map(csvCell).join(";"), ...rows].join("\n");
    const href = URL.createObjectURL(new Blob(["\ufeff", csv], { type: "text/csv;charset=utf-8" }));
    const link = document.createElement("a"); link.href = href; link.download = "rooming-list-andes-essencial.csv"; link.click(); URL.revokeObjectURL(href);
  }
  const singles = reservations.filter((item) => item.room_type === "single").length;
  const doubles = reservations.length - singles;
  async function addRoom(event: React.FormEvent) { event.preventDefault(); const departureId = reservations[0]?.departure_id; if (!departureId || !roomLabel.trim()) return; try { await createRoomGroup({ departure_id: departureId, label: roomLabel.trim(), room_type: roomType }); setRoomLabel(""); await onChange(); } catch (error) { onNotice(error instanceof Error ? error.message : "Não foi possível criar o quarto."); } }
  async function assign(reservationId: string, roomGroupId: string) { if (!roomGroupId) return; try { await assignReservationToRoom(reservationId, roomGroupId); await onChange(); } catch (error) { onNotice(error instanceof Error ? error.message : "Não foi possível alocar o viajante."); } }
  return <section className="rooming-list"><div className="rooming-heading"><div><p className="module-eyebrow">OPERAÇÃO</p><h2>Plano de acomodação</h2><p>Andes Essencial · 10–17 mar 2027 · Mendoza, Argentina</p></div><button disabled={!reservations.length || reservations.some((reservation) => !groups.some((group) => group.room_group_members.some((member) => member.reservation_id === reservation.id)))} onClick={exportCsv}>Emitir CSV final</button></div><div className="rooming-stats"><article><span>Inscritos</span><strong>{reservations.length}</strong></article><article><span>Preferência duplo</span><strong>{doubles}</strong></article><article><span>Preferência single</span><strong>{singles}</strong></article></div>{reservations.length === 0 ? <div className="empty-records"><strong>A rooming list será formada automaticamente.</strong><p>Assim que uma inscrição real for concluída, ela aparecerá aqui com os dados necessários para hotel e operação.</p></div> : <><form className="room-form" onSubmit={addRoom}><input value={roomLabel} onChange={(event) => setRoomLabel(event.target.value)} placeholder="Ex.: Quarto 101" required /><select value={roomType} onChange={(event) => setRoomType(event.target.value as RoomGroupRecord["room_type"])}><option value="matrimonial">Matrimonial</option><option value="twin">Doble twin</option><option value="single">Single</option></select><button>Criar quarto</button></form><div className="room-groups">{groups.map((group) => <article key={group.id}><header><strong>{group.label}</strong><span>{group.room_type === "matrimonial" ? "Matrimonial" : group.room_type === "twin" ? "Doble twin" : "Single"}</span></header>{group.room_group_members.length ? group.room_group_members.map((member) => <p key={member.reservation_id}>{reservations.find((reservation) => reservation.id === member.reservation_id)?.clients?.full_name ?? "Viajante"}</p>) : <small>Sem viajantes alocados.</small>}</article>)}</div><div className="rooming-table"><div className="rooming-head"><span>Viajante</span><span>Preferência</span><span>Alocação</span><span>Segurança e saúde</span></div>{reservations.map((reservation) => { const client = reservation.clients; const current = groups.find((group) => group.room_group_members.some((member) => member.reservation_id === reservation.id)); return <article key={reservation.id}><div><strong>{client?.full_name ?? "Viajante"}</strong><small>{client?.email ?? "E-mail não informado"}</small></div><span>{reservation.room_type === "single" ? "Single" : "Duplo"}</span><select value={current?.id ?? ""} onChange={(event) => assign(reservation.id, event.target.value)}><option value="">Selecionar quarto</option>{groups.map((group) => <option key={group.id} value={group.id}>{group.label} · {group.room_type === "twin" ? "Doble twin" : group.room_type}</option>)}</select><div><strong>{client?.emergency_contact_name ?? "Contato pendente"}</strong><small>{client?.health_plan ?? "Plano de saúde pendente"}</small></div></article>; })}</div></>}</section>;
}

function ClientsModule({ clients, loading, onAction, onDeleted }: { clients: ClientRecord[]; loading: boolean; onAction: (message: string) => void; onDeleted: () => Promise<void> }) {
  const [open, setOpen] = useState(false); const [editingClient, setEditingClient] = useState<ClientRecord | null>(null); const [saving, setSaving] = useState(false); const blank = { full_name: "", email: "", phone: "", city: "", cpf: "", rg: "", passport_number: "", street: "", neighborhood: "", postal_code: "", emergency_contact_name: "", emergency_contact_phone: "", health_plan: "", health_plan_phone: "" }; const [form, setForm] = useState(blank);
  function openNewClient() { setEditingClient(null); setForm(blank); setOpen(true); }
  function openClientEditor(client: ClientRecord) { setEditingClient(client); setForm({ full_name: client.full_name ?? "", email: client.email ?? "", phone: client.phone ?? "", city: client.city ?? "", cpf: client.cpf ?? "", rg: client.rg ?? "", passport_number: client.passport_number ?? "", street: client.street ?? "", neighborhood: client.neighborhood ?? "", postal_code: client.postal_code ?? "", emergency_contact_name: client.emergency_contact_name ?? "", emergency_contact_phone: client.emergency_contact_phone ?? "", health_plan: client.health_plan ?? "", health_plan_phone: client.health_plan_phone ?? "" }); setOpen(true); }
  function closeEditor() { setOpen(false); setEditingClient(null); setForm(blank); }
  async function submit(event: React.FormEvent) { event.preventDefault(); setSaving(true); try { if (editingClient) { await updateClient(editingClient.id, form); await onDeleted(); onAction("Cadastro atualizado com sucesso."); } else { await createClient(form); await onDeleted(); onAction("Cliente cadastrado com sucesso."); } closeEditor(); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível salvar o cadastro."); } finally { setSaving(false); } }
  async function removeClient(client: ClientRecord) { if (!window.confirm(`Excluir definitivamente o cadastro de ${client.full_name}? Todas as inscrições, pagamentos e contatos vinculados a este cliente serão removidos.`)) return; setSaving(true); try { await deleteClientWithReservations(client.id); await onDeleted(); onAction("Cadastro e inscrições vinculadas foram excluídos."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível excluir o cadastro."); } finally { setSaving(false); } }
  const field = (key: keyof typeof form, label: string, type = "text", required = false) => <label>{label}<input type={type} value={form[key]} onChange={(e) => setForm({ ...form, [key]: e.target.value })} required={required} /></label>;
  return <section className="module-page"><p className="module-eyebrow">Relacionamento</p><h1>Clientes e viajantes</h1><p className="module-summary">Cadastros, dados essenciais para rooming list, contatos e preparação em uma única ficha.</p><section className="module-workspace clients-workspace"><div><h2>{loading ? "Carregando clientes…" : `${clients.length} clientes cadastrados`}</h2><p>{clients.length ? "Abra um cadastro para consultar ou atualizar os dados do viajante." : "Seu primeiro cadastro aparecerá aqui assim que for criado."}</p></div><button onClick={openNewClient}><Plus aria-hidden="true" />Novo cliente</button></section>{open && <form className="client-form" onSubmit={submit}><div className="client-form-heading"><div><h2>{editingClient ? "Editar cadastro" : "Ficha completa do viajante"}</h2><p>Dados usados para rooming list, segurança e operação da viagem.</p></div><button type="button" className="client-close" onClick={closeEditor} aria-label="Fechar edição"><X aria-hidden="true" /></button></div><h3>Identificação</h3>{field("full_name", "Nome completo", "text", true)}{field("cpf", "CPF")}{field("rg", "RG")}{field("passport_number", "Passaporte")}{field("email", "E-mail", "email", true)}{field("phone", "Telefone / WhatsApp", "tel", true)}<h3>Endereço</h3>{field("street", "Rua e número")}{field("neighborhood", "Bairro")}{field("city", "Cidade")}{field("postal_code", "CEP")}<h3>Segurança e saúde</h3>{field("emergency_contact_name", "Contato de segurança")}{field("emergency_contact_phone", "Telefone do contato", "tel")}{field("health_plan", "Plano de saúde")}{field("health_plan_phone", "Contato do plano", "tel")}<div className="client-form-actions"><button disabled={saving}>{saving ? "Salvando…" : editingClient ? "Salvar alterações" : "Salvar ficha do cliente"}</button>{editingClient && <button type="button" className="danger-button" disabled={saving} onClick={() => removeClient(editingClient)}>Excluir cadastro e inscrições</button>}</div></form>}{clients.length > 0 && <div className="clients-list">{clients.map((client) => <article key={client.id}><span>{client.full_name.split(" ").map((part) => part[0]).slice(0, 2).join("")}</span><div><strong>{client.full_name}</strong><small>{[client.city, client.email, client.phone].filter(Boolean).join(" · ")}</small></div><button onClick={() => openClientEditor(client)}>Editar cadastro →</button></article>)}</div>}</section>;
}

function DocumentsModule({ clients, loading }: { clients: ClientRecord[]; loading: boolean }) {
  const [filter, setFilter] = useState<"all" | "pending" | "complete">("all");
  const readiness = (client: ClientRecord) => {
    const items = [client.cpf || client.rg, client.passport_number, client.emergency_contact_name && client.emergency_contact_phone, client.health_plan && client.health_plan_phone];
    return items.filter(Boolean).length;
  };
  const visible = clients.filter((client) => filter === "all" || (filter === "complete" ? readiness(client) === 4 : readiness(client) < 4));
  const complete = clients.filter((client) => readiness(client) === 4).length;
  const pending = clients.length - complete;
  const indicator = (present: unknown, ok: string, waiting: string) => <Status tone={present ? "ok" : "warn"}>{present ? `● ${ok}` : `● ${waiting}`}</Status>;
  return <section className="module-page"><p className="module-eyebrow">Conferência operacional</p><h1>Documentos e saúde</h1><p className="module-summary">Confira as informações essenciais de cada viajante antes do embarque. Os dados vêm diretamente da ficha de inscrição.</p><div className="module-grid report-grid"><article><span>Fichas completas</span><strong>{complete}</strong><small>Documentos e segurança conferidos</small></article><article><span>Com pendências</span><strong>{pending}</strong><small>Viajantes que precisam de acompanhamento</small></article><article><span>Cadastros recebidos</span><strong>{clients.length}</strong><small>Inscrições reais do Andes Essencial</small></article></div><section className="module-workspace"><div><h2>Conferência por viajante</h2><p>{loading ? "Carregando fichas…" : "Use o filtro para priorizar quem ainda precisa complementar dados."}</p></div><div className="rooming-filter" aria-label="Filtrar documentos"><button className={filter === "all" ? "selected" : ""} onClick={() => setFilter("all")}>Todos</button><button className={filter === "pending" ? "selected" : ""} onClick={() => setFilter("pending")}>Pendentes</button><button className={filter === "complete" ? "selected" : ""} onClick={() => setFilter("complete")}>Completos</button></div></section>{visible.length === 0 ? <section className="empty-section"><h2>{clients.length ? "Nenhuma ficha neste filtro" : "Nenhuma ficha recebida ainda"}</h2><p>{clients.length ? "Altere o filtro para visualizar os demais viajantes." : "Assim que um viajante concluir a inscrição, os documentos aparecerão aqui para conferência."}</p></section> : <div className="document-list">{visible.map((client) => <article key={client.id}><header><div><strong>{client.full_name}</strong><small>{client.email || "E-mail não informado"} · {client.phone || "Telefone não informado"}</small></div><b>{readiness(client)}/4 itens</b></header><div className="document-statuses"><div>{indicator(client.cpf || client.rg, "Identidade informada", "CPF ou RG pendente")}<small>{[client.cpf && "CPF", client.rg && "RG"].filter(Boolean).join(" · ") || ""}</small></div><div>{indicator(client.passport_number, "Passaporte informado", "Passaporte pendente")}<small>{client.passport_number || ""}</small></div><div>{indicator(client.emergency_contact_name && client.emergency_contact_phone, "Contato de segurança", "Contato de segurança pendente")}<small>{client.emergency_contact_name || ""}</small></div><div>{indicator(client.health_plan && client.health_plan_phone, "Saúde informada", "Plano ou seguro pendente")}<small>{client.health_plan || ""}</small></div></div></article>)}</div>}</section>;
}

function ContractDocumentsModule({ departure, reservations, payments }: { departure: DepartureRecord; reservations: ReservationRecord[]; payments: PaymentRecord[] }) {
  // Conteúdo transcrito dos PDFs comerciais de cada saída. Ao atualizar um PDF,
  // a lista correspondente também precisa ser atualizada antes de novos contratos.
  const contracts: Record<string, { activity: string; included: string[]; excluded: string[]; risks: string }> = {
    "andes-essencial": { activity: "trekking de montanha, com deslocamentos em altitude e atividades ao ar livre na região de Mendoza", included: ["07 diárias em pousadas ou hotéis padrão turístico ou superior com café da manhã", "01 almoço harmonizado 4 passos Bodega Los Toneles ou similar", "01 jantar harmonizado 4 passos Bodega Lagarde ou similar", "01 ingresso para Trekking de um dia Parque Provincial Aconcágua", "01 ingresso Reserva Natural Divisadero Largo", "01 ingresso Parque Provincial Cordón del Plata", "01 camiseta Ekonova Adventure", "transportes mencionados no programa", "guia Cadastur Brasil e América do Sul, com treinamento em medicina avançada em áreas remotas pela WMA International, acompanhando todo o percurso", "ingressos aos atrativos mencionados no programa"], excluded: ["refeições almoços jantares lanches e bebidas, salvo quando especificado como incluído", "custos com deslocamentos não mencionados no cronograma", "hospedagem não mencionada no cronograma", "qualquer item não mencionado como incluído no pacote ou que não tenha sido explicitamente citado anteriormente", "hospedagem solo, com acréscimo de US$ 300,00"], risks: "altitude, clima variável, trilhas e terrenos irregulares, deslocamentos em áreas remotas e esforço físico compatível com a atividade" },
    "trekking-caminhos-do-ouro": { activity: "trekking pelas montanhas e caminhos históricos de Minas Gerais", included: ["7 acomodações em pousadas com quartos duplos", "café da manhã todos os dias e jantar descrito no programa", "assistência logística e atendimento ilimitado durante toda a estadia", "6 cafés da manhã e 2 almoços inclusos", "7 noites de hotel", "5 dias de trekking", "entradas nos atrativos mencionados", "guia Cadastur Brasil e América do Sul, com treinamento em medicina avançada em áreas remotas pela WMA International, acompanhando todo o percurso"], excluded: ["refeições almoços jantares lanches e bebidas, salvo quando especificado como incluído", "despesas e responsabilidades decorrentes de acidentes durante o evento, quando de responsabilidade do participante inscrito ou de terceiros", "hospedagem solo, com acréscimo de R$ 700,00"], risks: "trilhas, subidas e descidas, terreno irregular, variações climáticas, fadiga e distância de centros de atendimento" },
    "trekking-atacama-essencia-2027": { activity: "trekking e experiências culturais no deserto do Atacama", included: ["08 noites no Hotel Tocona, em San Pedro de Atacama, de 16 a 24 de setembro de 2027", "café da manhã durante a hospedagem", "recepção e assistência no Aeroporto El Loa, em Calama", "transfers privativos Calama San Pedro Calama", "todos os transportes terrestres previstos no roteiro, em veículo adequado para 12 passageiros", "transfers para Catarpe, Gêiseres del Tatio, Machuca, Vallecitos, Guatín, Puritama, Valle del Arcoíris, Yerbas Buenas, Cejar Piedra Chaxa, Toconao e turismo astronômico", "apoio logístico durante os trekkings", "ingressos para Pukará de Quitor, Catarpe e Garganta del Diablo, Gêiseres del Tatio, Termas de Puritama, Valle del Arcoíris, Yerbas Buenas, complexo Cejar Piedra e Laguna Chaxa", "turismo astronômico com telescópios", "jantar de recepção no Restaurante Adobe", "café da manhã durante a excursão aos Gêiseres del Tatio", "piquenique no Magic Bus com queijos frutas pães água e vinhos chilenos", "guias e acompanhamento", "guia ou coordenador Cadastur com treinamento WAFA pela WMAI durante toda a viagem", "guia especializado durante o turismo astronômico", "apoio e acompanhamento do grupo durante as atividades", "coordenação dos transportes ingressos reservas e horários dos atrativos"], excluded: ["refeições almoços jantares lanches e bebidas, salvo quando especificado como incluído", "custos com deslocamentos não mencionados no cronograma", "hospedagem não mencionada no cronograma", "qualquer item não mencionado como incluído no pacote ou que não tenha sido explicitamente citado anteriormente", "hospedagem solo, com acréscimo de US$ 450,00"], risks: "altitude, clima árido, grande amplitude térmica, terreno irregular, exposição solar e distância de centros de atendimento" },
    "biketour-caminhos-do-ouro": { activity: "biketour por estradas rurais, trilhas e caminhos históricos de Minas Gerais", included: ["6 acomodações em pousadas com quartos duplos", "café da manhã todos os dias e jantar descrito no programa", "veículo de apoio para transporte das bagagens e apoio caso necessário", "assistência logística e atendimento ilimitado durante toda a estadia", "6 cafés da manhã e 2 jantares inclusos", "6 noites de hotel", "5 dias de pedal", "tracks GPX para GPS", "rastreador SPOT via satélite", "guia Cadastur Brasil e América do Sul, com treinamento em medicina avançada em áreas remotas pela WMA International, acompanhando todo o percurso"], excluded: ["refeições almoços jantares lanches e bebidas, salvo quando especificado como incluído", "despesas e responsabilidades decorrentes de acidentes durante o evento, quando de responsabilidade do participante inscrito ou de terceiros", "hospedagem solo, com acréscimo de R$ 700,00"], risks: "tráfego, quedas, terreno irregular, falhas mecânicas, variações climáticas e esforço físico prolongado" },
  };
  const profile = contracts[departure.trips?.slug ?? ""];
  const formatMoney = (value: number) => new Intl.NumberFormat(departure.currency === "BRL" ? "pt-BR" : "en-US", { style: "currency", currency: departure.currency }).format(value / 100);
  const date = (value: string) => new Date(`${value}T12:00:00`).toLocaleDateString("pt-BR");
  const issuedOn = () => new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "long", year: "numeric" }).format(new Date());
  const escape = (value: string | null | undefined) => (value ?? "Não informado").replace(/[&<>\"]/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '\"': "&quot;" }[character] ?? character));
  function generate(reservation: ReservationRecord) {
    const client = reservation.clients; if (!client || !profile) return;
    const schedule = payments.filter((item) => item.reservation_id === reservation.id).sort((a, b) => a.due_on.localeCompare(b.due_on));
    const total = schedule.reduce((sum, item) => sum + item.amount_cents, 0);
    const paymentRows = schedule.map((item) => `<li>${escape(item.reference || "Pagamento")}: <b>${formatMoney(item.amount_cents)}</b> - vencimento ${date(item.due_on)}</li>`).join("");
    const list = (items: string[]) => `<ul>${items.map((item) => `<li>${escape(item)}</li>`).join("")}</ul>`;
    const legalTerms = `<h2>5. Deveres da contratada</h2><p>A CONTRATADA fornecerá informações claras sobre itinerário, esforço físico, riscos previsíveis, hospedagem, preço, inclusões, exclusões, equipamentos e alterações conhecidas; manterá canal de atendimento e adotará medidas razoáveis de prevenção e resposta a emergências.</p><h2>6. Deveres do contratante e participante</h2><p>O CONTRATANTE prestará informações verdadeiras e atualizadas, respeitará as orientações da equipe, a legislação aplicável, o ambiente e o grupo. Deverá manter capacidade física e técnica compatível, comparecer nos horários, usar os equipamentos exigidos e comunicar imediatamente qualquer mal-estar, acidente ou afastamento da atividade.</p><h2>7. Saúde, seguro e aptidão</h2><p>O PARTICIPANTE deverá informar condições de saúde, medicamentos, alergias, restrições e contato de emergência relevantes à segurança. O seguro viagem, quando não incluído no roteiro, deverá ser providenciado pelo PARTICIPANTE com cobertura compatível à atividade, sem afastar os deveres legais da CONTRATADA.</p><h2>8. Segurança, riscos e decisões operacionais</h2><p>O PARTICIPANTE declara ciência dos riscos inerentes descritos neste contrato e no Anexo Único. A equipe poderá alterar, encurtar, neutralizar ou cancelar etapas por segurança, clima, acesso ou determinação de autoridade, preservando a finalidade da viagem sempre que possível.</p><h2>9. Direito de arrependimento</h2><p>Quando a contratação ocorrer fora do estabelecimento comercial, o CONTRATANTE poderá exercer o direito de arrependimento em até 7 dias contados da assinatura, mediante comunicação inequívoca, nos termos do art. 49 do Código de Defesa do Consumidor.</p><h2>10. Cancelamento pelo participante, substituição e não comparecimento</h2><p>Após o prazo de arrependimento, o cancelamento deverá ser solicitado por escrito. Poderá haver retenção proporcional, limitada aos custos comprovadamente não recuperáveis e ao prejuízo efetivo demonstrado, sem impor desvantagem exagerada ao CONTRATANTE.</p><p>A interpretação desta cláusula observará especialmente os arts. 6º, incisos III, IV e V, e 51, inciso IV, do Código de Defesa do Consumidor, bem como os arts. 421 e 422 do Código Civil, que asseguram informação clara, equilíbrio contratual, função social e boa-fé.</p><p>Quando tecnicamente possível e permitido pelos fornecedores, o CONTRATANTE poderá indicar substituto para sua vaga, sujeito às exigências documentais, de saúde e operacionais do roteiro. O não comparecimento sem aviso não elimina os custos já assumidos e comprovadamente não recuperáveis.</p><h2>11. Alteração ou cancelamento pela contratada</h2><p>Se a CONTRATADA cancelar a viagem antes do início por decisão empresarial ou ausência do número mínimo informado, o CONTRATANTE poderá escolher reembolso integral, crédito sem penalidade ou outro roteiro/data com ajuste de diferenças. Em fato inevitável e alheio ao controle razoável, serão priorizadas remarcação, alternativa equivalente ou crédito, respeitados os direitos legais.</p><h2>12. Responsabilidade, terceiros e assistência</h2><p>A CONTRATADA responde pela adequada organização e execução dos serviços que fornecer diretamente ou integrar ao pacote, inclusive pela suficiência das informações e assistência devida, nos limites da legislação. Serviços opcionais contratados diretamente pelo PARTICIPANTE com terceiros não integram o pacote, ressalvadas as responsabilidades previstas em lei.</p><h2>13. Dados pessoais, saúde, rastreamento e imagem</h2><p>Os dados pessoais serão tratados para executar a viagem, proteger a vida, cumprir obrigações legais e exercer direitos, observando a LGPD. Poderão ser compartilhados no mínimo necessário com hospedagens, guias, transportadores, prestadores de saúde, resgate, seguradoras, plataformas de pagamento e autoridades. Uso promocional identificável de imagem e voz depende de autorização separada e facultativa.</p><h2>14. Comunicações, assinatura e disposições gerais</h2><p>Comunicações relevantes poderão ser feitas por e-mail, WhatsApp ou outro canal informado pelas partes, preservando-se o registro. Alterações relevantes exigem confirmação escrita. A assinatura eletrônica que identifique o signatário e demonstre autoria e integridade será válida.</p><h2>15. Solução de conflitos e foro</h2><p>As partes buscarão solução direta e poderão utilizar consumidor.gov.br, Procon ou mediação. Não havendo acordo, o consumidor poderá propor ação no foro de seu domicílio ou em outro foro competente previsto em lei.</p><h2>Anexo Único - Ciência de riscos e compromisso de segurança</h2><p>O PARTICIPANTE declara que recebeu oportunidade de esclarecer dúvidas, compreende os riscos previsíveis da atividade, informará sintomas, acidentes e mudança de saúde, seguirá as orientações da equipe e compreende que a ciência de riscos inerentes não representa aceitação de falhas evitáveis de segurança.</p>`;
    const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Contrato - ${escape(client.full_name)}</title><style>@page{size:A4;margin:22mm}body{font-family:Arial,sans-serif;color:#172f25;line-height:1.5;font-size:11pt}h1,h2{font-family:Georgia,serif;color:#114532}h1{text-align:center;font-size:19pt;margin:0 0 4px}h2{font-size:13pt;margin:24px 0 8px}.subtitle{text-align:center;margin:0 0 24px}.parties{border:1px solid #cbd7ce;padding:12px;margin:14px 0}.parties p{margin:4px 0}li{margin:4px 0}.signature{margin-top:46px;display:flex;gap:50px;justify-content:space-between;text-align:center}.signature div{width:45%;border-top:1px solid #222;padding-top:7px}.note{font-size:9pt;color:#52685a}@media print{button{display:none}}</style></head><body><h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS TURÍSTICOS</h1><p class="subtitle"><b>${escape(departure.trips?.title)}</b> · ${date(departure.starts_on)} a ${date(departure.ends_on)}</p><section class="parties"><p><b>CONTRATADA:</b> Destino Ativo Eventos e Turismo Ltda., CNPJ 57.263.841/0001-09, doravante CONTRATADA.</p><p><b>CONTRATANTE:</b> ${escape(client.full_name)}, CPF ${escape(client.cpf)}, RG ${escape(client.rg)}, passaporte ${escape(client.passport_number)}, endereço ${escape(client.street)}, ${escape(client.neighborhood)}, ${escape(client.city)}, CEP ${escape(client.postal_code)}, e-mail ${escape(client.email)}, telefone ${escape(client.phone)}, doravante CONTRATANTE.</p></section><h2>1. Objeto, natureza da atividade e documentos da viagem</h2><p>A CONTRATADA prestará os serviços turísticos referentes ao roteiro <b>${escape(departure.trips?.title)}</b>, em ${escape(departure.trips?.destination)}, caracterizado como ${escape(profile.activity)}. A acomodação escolhida é <b>${reservation.room_type === "single" ? "quarto single" : "quarto duplo compartilhado"}</b>. Integram este contrato a oferta, o roteiro comercial, o Anexo Único, comprovantes de pagamento e comunicações que confirmem condições específicas.</p><h2>2. Preço, acomodação e condições de pagamento</h2><p>O valor total contratado é <b>${formatMoney(total)}</b>. O cronograma individual aceito pelo CONTRATANTE é:</p>${paymentRows ? `<ul>${paymentRows}</ul>` : "<p>O cronograma será definido pela equipe Ekonova.</p>"}<p>O pagamento depende de compensação. Em caso de atraso, poderão incidir multa moratória de 2% e juros de 1% ao mês, proporcionalmente, além de correção legal.</p><h2>3. Serviços incluídos</h2>${list(profile.included)}<h2>4. Serviços não incluídos</h2>${list(profile.excluded)}${legalTerms}<p class="note">Este documento é gerado a partir da inscrição e deve ser revisado pela equipe antes da assinatura.</p><p>Palhoça/SC, ____ de __________________ de ${new Date().getFullYear()}.</p><div class="signature"><div>${escape(client.full_name)}<br>CONTRATANTE</div><div>DESTINO ATIVO EVENTOS E TURISMO LTDA.<br>CONTRATADA</div></div><script>window.onload=()=>window.print()<\/script></body></html>`;
    const biketourHtml = departure.trips?.slug === "biketour-caminhos-do-ouro" ? `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Contrato - ${escape(client.full_name)}</title><style>@page{size:A4;margin:22mm}body{font-family:Arial,sans-serif;color:#172f25;line-height:1.5;font-size:11pt}h1,h2{font-family:Georgia,serif;color:#114532}h1{text-align:center;font-size:19pt;margin:0 0 4px}h2{font-size:13pt;margin:24px 0 8px}.subtitle{text-align:center;margin:0 0 24px}.parties{border:1px solid #cbd7ce;padding:12px;margin:14px 0}.parties p{margin:4px 0}li{margin:4px 0}.signature{margin-top:46px;display:flex;gap:50px;justify-content:space-between;text-align:center}.signature div{width:45%;border-top:1px solid #222;padding-top:7px}.note{font-size:9pt;color:#52685a}@media print{button{display:none}}</style></head><body><h1>CONTRATO DE PRESTAÇÃO DE SERVIÇOS TURÍSTICOS</h1><p class="subtitle"><b>BIKETOUR CAMINHOS DO OURO</b> · ${date(departure.starts_on)} A ${date(departure.ends_on)}</p><section class="parties"><p><b>CONTRATADA:</b> Destino Ativo Eventos e Turismo Ltda., CNPJ 57.263.841/0001-09, com sede na Rua do Albatroz, Bairro Pedra Branca, Palhoça/SC, CEP 88137-290, doravante CONTRATADA.</p><p><b>CONTRATANTE:</b> Nome: ${escape(client.full_name)}. CPF: ${escape(client.cpf)}. RG: ${escape(client.rg)}. Endereço: ${escape(client.street)}, ${escape(client.neighborhood)}, ${escape(client.city)}, CEP ${escape(client.postal_code)}. E-mail: ${escape(client.email)}. Telefone: ${escape(client.phone)}, doravante CONTRATANTE.</p></section><p>As partes celebram este contrato de consumo, regido pelo Código de Defesa do Consumidor, pela Lei Geral do Turismo em sua redação vigente, pelo Decreto do Comércio Eletrônico quando aplicável, pela Lei Geral de Proteção de Dados Pessoais e pelas demais normas pertinentes, conforme as cláusulas abaixo e o Anexo Único.</p><h2>1. OBJETO, NATUREZA DA ATIVIDADE E DOCUMENTOS DA VIAGEM</h2><p><b>1.1.</b> A CONTRATADA organizará e prestará o pacote turístico Biketour Caminhos do Ouro, em ${escape(departure.trips?.destination)}, de ${date(departure.starts_on)} a ${date(departure.ends_on)}, composto pelos serviços, hospedagens, percursos e atividades previstos no roteiro comercial.</p><p><b>1.2.</b> Integram este contrato a oferta e o roteiro comercial entregues ao consumidor, o Anexo Único, os comprovantes de pagamento, a lista de equipamentos e as comunicações que confirmem condições específicas. Informação publicitária suficientemente precisa vincula a CONTRATADA; em caso de divergência, será observada a condição mais favorável ao consumidor, salvo ajuste posterior expresso e válido.</p><p><b>1.3.</b> Trata-se de turismo de aventura com ciclismo em estradas rurais, trilhas, caminhos históricos, terra, cascalho, subidas e descidas, circulação eventual de veículos e animais, variação climática e limitação de sinal de telefonia. Distâncias, altimetrias, horários e pontos de passagem são aproximados e podem ser adaptados por segurança, acesso ou determinação de autoridade.</p><h2>2. PREÇO, ACOMODAÇÃO E CONDIÇÕES DE PAGAMENTO</h2><p><b>2.1.</b> O preço-base por pessoa é de ${formatMoney(departure.price_cents)}, em acomodação compartilhada, quarto duplo. A acomodação escolhida é <b>${reservation.room_type === "single" ? "individual, com suplemento já incorporado ao preço final" : "compartilhada, em quarto duplo"}</b>. O valor total contratado é <b>${formatMoney(total)}</b>.</p><p><b>2.2.</b> O CONTRATANTE escolheu a seguinte condição diretamente neste contrato:</p>${paymentRows ? `<ul>${paymentRows}</ul>` : "<p>O cronograma será definido pela equipe Ekonova.</p>"}<p><b>2.3.</b> O suplemento individual e eventuais serviços adicionais estão somados ao preço final apresentado acima e discriminados antes do pagamento. Nenhuma modalidade será considerada escolhida sem indicação do total, das parcelas, vencimentos e meio de pagamento neste contrato ou em confirmação escrita aceita pelas partes.</p><p><b>DESTAQUE SOBRE O PARCELAMENTO:</b> prevalecerá exclusivamente o cronograma individualizado e aceito por escrito. A referência a prazo final somente produzirá efeito se ano, vencimentos, valores e número de parcelas estiverem preenchidos antes da assinatura.</p><p><b>2.4.</b> O pagamento por PIX poderá ser realizado para a chave CNPJ 57.263.841/0001-09, Banco Inter, agência 0001, conta 38987183-4, ou para outra conta confirmada por canal oficial. A quitação depende da compensação. Tarifas ou custos do meio de pagamento serão previamente informados e constarão do valor total.</p><p><b>2.5.</b> No atraso, poderão incidir multa moratória de 2% e juros de 1% ao mês, proporcionalmente, além de correção legal. A reserva somente poderá ser cancelada após notificação, oportunidade razoável de regularização e prestação de contas segundo a cláusula 11.</p><h2>3. SERVIÇOS INCLUÍDOS</h2><p><b>3.1.</b> O preço-base inclui exatamente os seguintes serviços, conforme a oferta e o roteiro comercial:</p>${list(profile.included)}<p><b>3.2.</b> Hotéis, pousadas, restaurantes e horários poderão ser substituídos por alternativas de categoria e finalidade equivalentes ou superiores quando houver indisponibilidade, segurança, clima ou necessidade operacional, sem redução injustificada do pacote.</p><h2>4. SERVIÇOS NÃO INCLUÍDOS</h2><p><b>CLÁUSULA LIMITATIVA:</b> todo item não indicado como incluído será suportado pelo PARTICIPANTE. Esta exclusão não afasta a responsabilidade legal da CONTRATADA por defeito do serviço, informação inadequada ou falha de segurança que lhe seja imputável.</p><p><b>4.1.</b> Não integram o preço-base:</p>${list(profile.excluded)}<p><b>4.2.</b> Despesas decorrentes de acidentes ou emergências serão alocadas conforme a causa do evento, a cobertura de seguro e a responsabilidade legal. O PARTICIPANTE suportará despesas decorrentes de risco inerente, condição pessoal, conduta própria ou de terceiro estranho ao serviço; a CONTRATADA responderá nos limites legais quando houver falha do serviço ou descumprimento de seus deveres.</p><h2>5. DEVERES DA CONTRATADA</h2><p><b>5.1.</b> Fornecer informações claras sobre itinerário, esforço físico, riscos previsíveis, hospedagem, preço, inclusões, exclusões, equipamentos e alterações conhecidas; manter cadastro e habilitações aplicáveis; selecionar prestadores compatíveis; manter canal de atendimento; e adotar medidas razoáveis de prevenção e resposta a emergências.</p><p><b>5.2.</b> Disponibilizar, antes da partida, os arquivos GPX, instruções de bagagem e equipamentos, contatos operacionais, locais e horários de encontro, além da identificação dos prestadores que devam ser conhecidos pelo PARTICIPANTE.</p><p><b>5.3.</b> Informar mudanças relevantes com a maior antecedência possível. Se houver redução objetiva do serviço, oferecer alternativa equivalente ou superior sem custo ou restituir proporcionalmente o que não for prestado, conforme a causa, os valores recuperáveis e os direitos do consumidor.</p><h2>6. DEVERES DO CONTRATANTE E DO PARTICIPANTE</h2><p><b>6.1.</b> Prestar informações verdadeiras e atualizadas; informar condições de saúde, medicamentos, alergias, restrições alimentares e contato de emergência; manter capacidade física e técnica compatível; comparecer nos horários; respeitar as orientações do guia, a legislação de trânsito, o ambiente, as comunidades e o grupo; e não participar sob efeito de álcool ou substância que comprometa a segurança.</p><p><b>6.2.</b> Levar bicicleta apropriada, revisada e em condições seguras, capacete de ciclismo de uso obrigatório, vestuário e equipamentos indicados, hidratação, alimentação de uso pessoal, medicação prescrita e dispositivo apto a ler o GPX. A CONTRATADA poderá impedir a largada sem equipamento essencial, mediante justificativa e registro.</p><p><b>6.3.</b> Zelar por documentos, dinheiro, eletrônicos, bicicleta, bagagem e objetos pessoais. Quando um bem for formalmente entregue à custódia da CONTRATADA ou do transportador por ela contratado, deverá ser tratado com cuidado compatível, preservada a responsabilidade prevista em lei.</p><p><b>6.4.</b> Comunicar imediatamente mal-estar, acidente, dano, perda de equipamento, afastamento da rota ou decisão de abandonar a etapa, permitindo que a equipe adote providências razoáveis. A falta de comunicação não implica perda automática de direitos, mas poderá ser considerada quando tiver impedido a mitigação de danos.</p><h2>7. SAÚDE, SEGURO E APTIDÃO</h2><p><b>CONDIÇÃO ESSENCIAL DE SEGURANÇA:</b> o Biketour exige esforço físico prolongado. O PARTICIPANTE deverá avaliar sua saúde, preparar-se adequadamente e informar, por canal reservado, condições relevantes para a segurança. A ciência dos riscos não representa renúncia a direitos.</p><p><b>7.1.</b> O PARTICIPANTE deverá informar e atualizar, até a partida e por canal reservado, condições de saúde, medicamentos, alergias, restrições e contato de emergência relevantes para a segurança. A CONTRATADA poderá solicitar avaliação ou atestado médico quando houver indicação objetiva de risco, sem que o documento transfira automaticamente responsabilidades.</p><p><b>7.2.</b> Como seguro viagem/aventura e acidentes pessoais não estão incluídos, o PARTICIPANTE deverá apresentar, até 15 dias antes da viagem, apólice válida para ciclismo recreativo, com assistência médica e cobertura de remoção ou resgate compatível com a rota, salvo dispensa expressa e escrita da CONTRATADA.</p><p><b>7.3.</b> Em emergência, a CONTRATADA poderá acionar atendimento, remoção ou resgate e compartilhar apenas os dados necessários. Custos serão encaminhados inicialmente ao seguro; eventual saldo será alocado conforme a causa e a responsabilidade legal, vedada transferência automática de custos decorrentes de falha da CONTRATADA.</p><h2>8. SEGURANÇA, RISCOS E DECISÕES OPERACIONAIS</h2><p><b>8.1.</b> O PARTICIPANTE declara ter recebido informação sobre os riscos previsíveis descritos no Anexo Único, entre eles quedas, colisões, tráfego, falha mecânica, desidratação, exaustão, hipotermia ou hipertermia, animais, variação climática, baixa visibilidade, terreno irregular, locais remotos e demora de socorro.</p><p><b>8.2.</b> O guia poderá alterar, encurtar, neutralizar ou cancelar etapa e poderá interromper a participação de pessoa que apresente risco relevante, desobedeça instrução, não possua equipamento obrigatório ou comprometa o grupo. A decisão deverá ser proporcional, fundamentada e, sempre que possível, registrada e comunicada.</p><p><b>8.3.</b> Arquivos GPX e rastreador SPOT são recursos de apoio. Não substituem atenção, sinalização, cumprimento das orientações, avaliação do terreno ou comunicação de emergência, e podem sofrer limitações de bateria, cobertura, precisão, sinal, equipamento ou condições ambientais.</p><p><b>8.4.</b> O veículo de apoio circulará apenas por vias acessíveis e seguras, poderá atender o grupo por pontos definidos e não equivale a ambulância, resgate especializado ou garantia de recolhimento imediato em qualquer trecho. Isso não afasta o dever de assistência e de adoção de providências razoáveis em emergência.</p><h2>9. DIREITO DE ARREPENDIMENTO</h2><p><b>9.1.</b> Quando a contratação ocorrer pela internet, telefone, WhatsApp ou fora do estabelecimento comercial, o CONTRATANTE poderá desistir em até 7 dias contados da assinatura, mediante comunicação inequívoca pelo mesmo canal ou por outro meio eficaz. Os valores pagos serão restituídos integralmente, conforme o art. 49 do Código de Defesa do Consumidor e a regulamentação aplicável.</p><p><b>9.2.</b> A CONTRATADA enviará confirmação do pedido de arrependimento e comunicará imediatamente às instituições financeiras para cancelamento ou estorno, sem criar obstáculos ou exigir justificativa.</p><h2>10. CANCELAMENTO PELO PARTICIPANTE, SUBSTITUIÇÃO E NÃO COMPARECIMENTO</h2><p><b>CLÁUSULA LIMITATIVA - RETENÇÕES:</b> após o prazo de arrependimento, o cancelamento pode gerar retenção proporcional e custos comprovadamente não recuperáveis. A soma nunca poderá superar o preço contratado nem o prejuízo efetivo demonstrado.</p><p><b>10.1.</b> O cancelamento deverá ser solicitado por escrito. Sobre a parcela correspondente aos serviços próprios ainda recuperáveis da CONTRATADA poderá incidir multa compensatória de 10% com 60 dias ou mais de antecedência; 20% entre 59 e 30 dias; e 30% com 29 dias ou menos.</p><p><b>10.2.</b> Custos de terceiros já contratados e comprovadamente não reembolsáveis poderão ser deduzidos separadamente, desde que individualizados. A multa da cláusula 10.1 incidirá apenas sobre a base remanescente, evitando dupla cobrança. Valores recuperados posteriormente serão repassados ao CONTRATANTE.</p><p><b>10.3.</b> O demonstrativo de cálculo será enviado e o saldo será restituído em até 30 dias após a apuração dos reembolsos dos fornecedores, com informação das pendências ainda dependentes de terceiro e atualização quando legalmente cabível.</p><p><b>10.4.</b> A substituição do PARTICIPANTE será aceita quando tecnicamente possível e permitida pelos fornecedores, mediante aprovação cadastral, assinatura dos documentos exigidos e pagamento apenas de diferenças tarifárias e custos efetivos. Serviços nominativos seguirão a regra do respectivo fornecedor.</p><p><b>10.5.</b> Não comparecimento, atraso que impeça o embarque ou largada, abandono voluntário, falta de equipamento obrigatório ou impedimento decorrente de informação ou documento irregular não gera devolução automática dos serviços já disponibilizados ou irrecuperáveis. Serviços recuperáveis serão apurados conforme as cláusulas anteriores.</p><h2>11. ALTERAÇÃO OU CANCELAMENTO PELA CONTRATADA</h2><p><b>11.1.</b> Se a CONTRATADA cancelar a viagem antes do início por decisão empresarial ou por ausência do número mínimo informado por escrito na contratação, o CONTRATANTE escolherá entre reembolso integral, crédito sem penalidade ou outro roteiro/data com acerto de diferenças. A escolha será registrada por escrito.</p><p><b>11.2.</b> Em fato inevitável e alheio ao controle razoável - como evento climático severo, fechamento de vias ou atrativos, desastre natural, epidemia, conflito, ordem de autoridade ou impossibilidade segura de operação -, serão priorizadas remarcação, substituição equivalente ou crédito. Sem acordo, haverá prestação de contas e devolução dos serviços próprios não prestados e dos valores recuperados, respeitados os direitos legais do consumidor.</p><p><b>11.3.</b> Durante a execução, a CONTRATADA poderá ajustar rota, horário, meio de hospedagem, restaurante ou logística por segurança ou necessidade comprovada, preservando finalidade, duração e padrão sempre que possível. Se houver redução relevante e não compensada, será feita restituição proporcional.</p><p><b>11.4.</b> Despesas extraordinárias serão alocadas conforme a causa, a responsabilidade legal, a cobertura de seguro e a possibilidade de reembolso, sem transferência automática ao PARTICIPANTE.</p><h2>12. RESPONSABILIDADE, TERCEIROS E ASSISTÊNCIA</h2><p><b>12.1.</b> A CONTRATADA responde pela adequada organização e execução dos serviços que fornecer diretamente ou integrar ao pacote, inclusive pela suficiência das informações e pela assistência devida, nos termos da legislação de consumo. Nenhuma cláusula exclui responsabilidade por defeito do serviço, negligência ou violação de dever legal.</p><p><b>12.2.</b> Serviço opcional adquirido diretamente pelo PARTICIPANTE de terceiro, sem oferta, cobrança, organização ou intermediação da CONTRATADA, não integra o pacote. Isso não afasta a responsabilidade que a lei atribua à CONTRATADA por serviço que tenha efetivamente ofertado, organizado ou intermediado.</p><p><b>12.3.</b> Ocorrências devem ser comunicadas tão logo possível ao guia ou canal oficial para permitir correção e assistência. Após a viagem, reclamações poderão ser formuladas dentro dos prazos legais, sem restrição ao Procon, consumidor.gov.br, mediação ou via judicial.</p><h2>13. DADOS PESSOAIS, SAÚDE, RASTREAMENTO E IMAGEM</h2><p><b>13.1.</b> A CONTRATADA tratará dados cadastrais, financeiros, de viagem, localização e, quando necessário, dados de saúde para executar o contrato, proteger a vida, cumprir obrigações legais e exercer direitos, observando finalidade, necessidade, segurança, transparência e os direitos previstos na LGPD.</p><p><b>13.2.</b> Dados poderão ser compartilhados no mínimo necessário com hospedagens, restaurantes, guias, transportadores, prestadores de saúde e resgate, seguradoras, plataformas de pagamento e autoridades. Dados de saúde e localização não serão utilizados para publicidade e terão acesso restrito.</p><p><b>13.3.</b> O uso promocional identificável de imagem e voz dependerá de autorização separada, destacada e facultativa. A recusa não impede a contratação. A autorização poderá ser revogada para usos futuros, respeitados conteúdo já produzido, obrigações legais e limitações técnicas proporcionais.</p><h2>14. COMUNICAÇÕES, ASSINATURA E DISPOSIÇÕES GERAIS</h2><p><b>14.1.</b> Comunicações relevantes serão feitas por e-mail, WhatsApp ou outro canal informado pelas partes, preservando-se o registro. Alterações relevantes exigem confirmação escrita e não poderão reduzir direitos legais.</p><p><b>14.2.</b> A assinatura eletrônica que permita identificar o signatário e demonstrar autoria e integridade será válida, inclusive por plataforma aceita pelas partes, nos termos da legislação aplicável, sem prejuízo da assinatura manuscrita.</p><p><b>14.3.</b> A eventual nulidade de uma disposição não invalida as demais. Tolerância não significa renúncia. Este contrato será interpretado segundo a boa-fé, a função social, o equilíbrio contratual e a condição mais favorável ao consumidor quando houver ambiguidade em cláusula de adesão.</p><h2>15. SOLUÇÃO DE CONFLITOS E FORO</h2><p><b>15.1.</b> As partes buscarão solução direta e poderão utilizar consumidor.gov.br, Procon ou mediação. Não havendo acordo, o consumidor poderá propor ação no foro de seu domicílio ou em outro foro competente previsto em lei. O foro de Palhoça/SC somente será utilizado quando não dificultar a defesa do consumidor e houver concordância válida.</p><p>Palhoça/SC, ${issuedOn()}.</p><div class="signature"><div>${escape(client.full_name)}<br>CONTRATANTE</div><div>DESTINO ATIVO EVENTOS E TURISMO LTDA.<br>CONTRATADA</div></div><h2>ANEXO ÚNICO - CIÊNCIA DE RISCOS E COMPROMISSO DE SEGURANÇA</h2><p>Este anexo informa riscos previsíveis e registra medidas de prevenção. Não representa renúncia a direitos nem exonera a CONTRATADA por defeito do serviço, negligência ou informação insuficiente.</p><ul><li>quedas, colisões, escorregões, torções, cortes, impacto e perda de controle em asfalto, terra, cascalho, lama, areia, pedras, buracos ou declives;</li><li>tráfego de veículos, máquinas, pedestres, ciclistas, animais e cruzamentos sem controle;</li><li>falha mecânica, pneu furado, quebra de componente, bateria ou dispositivo de navegação sem carga;</li><li>desidratação, hipoglicemia, exaustão, dor muscular, câimbras, queimadura solar, hipotermia, hipertermia e agravamento de condição preexistente;</li><li>chuva, vento, frio, calor, neblina, baixa visibilidade, raios, queda de galhos e mudança rápida de clima;</li><li>poeira, insetos, plantas, animais, água ou alimento capazes de causar reação;</li><li>distância de centros médicos, comunicação limitada, demora ou dificuldade de acesso do veículo de apoio, ambulância ou resgate; e</li><li>alteração, encurtamento, neutralização ou interrupção da etapa por segurança, acesso, clima ou determinação de autoridade.</li></ul><h2>DECLARAÇÕES DO PARTICIPANTE</h2><ul><li>Recebi oportunidade de esclarecer dúvidas sobre esforço, terreno, equipamento, suporte e riscos.</li><li>Informarei sintomas, acidentes, mudança de saúde e afastamento da rota sem demora.</li><li>Levarei bicicleta revisada, capacete obrigatório, equipamentos indicados, hidratação, alimentação e medicação pessoal.</li><li>Seguirei as orientações do guia e a legislação de trânsito e não participarei sob efeito de álcool ou substância incapacitante.</li><li>Compreendo que aceitar riscos inerentes não significa aceitar falhas evitáveis de segurança.</li></ul><div class="signature"><div>${escape(client.full_name)}<br>PARTICIPANTE</div><div>Data: ${issuedOn()}</div></div><script>window.onload=()=>window.print()<\/script></body></html>` : html;
    const contractHtml = biketourHtml
      .replace(`<div class="signature"><div>${escape(client.full_name)}<br>PARTICIPANTE</div><div>Data: ${issuedOn()}</div></div><script>`, '<p class="note">Este Anexo Único integra o contrato principal e é abrangido pela assinatura das partes realizada acima.</p><script>')
      .replace("<p><b>10.4.</b>", "<p>A interpretação desta cláusula observará especialmente os arts. 6º, incisos III, IV e V, e 51, inciso IV, do Código de Defesa do Consumidor, bem como os arts. 421 e 422 do Código Civil, que asseguram informação clara, equilíbrio contratual, função social e boa-fé.</p><p><b>10.4.</b>")
      .replace(`<title>Contrato - ${escape(client.full_name)}</title>`, `<title>Contrato - ${escape(departure.trips?.title)} - ${escape(client.full_name)}</title>`)
      .replace("Destino Ativo Eventos e Turismo Ltda., CNPJ 57.263.841/0001-09, doravante CONTRATADA.", "Destino Ativo Eventos e Turismo Ltda., CNPJ 57.263.841/0001-09, com sede na Rua do Albatroz, Bairro Pedra Branca, Palhoça/SC, CEP 88137-290, doravante CONTRATADA.")
      .replace("<style>@page{size:A4;margin:22mm}", "<style>@page{size:A4;margin:22mm}body{position:relative}.contract-watermark{position:fixed;top:0;left:0;width:100%;height:auto;opacity:.1;z-index:0;pointer-events:none}body>*:not(.contract-watermark){position:relative;z-index:1}@media print{.contract-watermark{display:block!important;-webkit-print-color-adjust:exact;print-color-adjust:exact}}")
      .replace("<body>", "<body><img class=\"contract-watermark\" src=\"https://www.ekonovaadv.com.br/destino-ativo-watermark.svg\" alt=\"\" aria-hidden=\"true\">")
      .replace("margin-top:46px", "margin-top:92px")
      .replace(/Palhoça\/SC, ____ de __________________ de \d{4}\./, `Palhoça/SC, ${issuedOn()}.`);
    const popup = window.open("", "_blank"); if (!popup) return; popup.opener = null; popup.document.write(contractHtml); popup.document.close();
  }
  return <section className="module-page"><p className="module-eyebrow">Documentação contratual</p><h2>Contratos da saída</h2><p className="module-summary">Gere manualmente o contrato individual para cada inscrição. O roteiro, o cliente, a acomodação, os valores e as parcelas são preenchidos automaticamente.</p>{!reservations.length ? <section className="empty-section"><h2>Nenhuma inscrição para contratar</h2><p>Os contratos aparecerão aqui assim que uma inscrição for recebida.</p></section> : <div className="clients-list">{reservations.map((reservation) => <article key={reservation.id}><span>{reservation.clients?.full_name.split(" ").map((part) => part[0]).slice(0, 2).join("") ?? "EC"}</span><div><strong>{reservation.clients?.full_name ?? "Viajante"}</strong><small>{reservation.room_type === "single" ? "Quarto single" : "Quarto duplo"} · {payments.filter((item) => item.reservation_id === reservation.id).length} lançamento(s)</small></div><button onClick={() => generate(reservation)}>Gerar contrato em PDF</button></article>)}</div>}</section>;
}

function CommunicationModule({ clients, logs, departures, onAction, onLogged }: { clients: ClientRecord[]; logs: ContactLogRecord[]; departures: DepartureRecord[]; onAction: (message: string) => void; onLogged: () => Promise<void> }) {
  const [selected, setSelected] = useState("Confirmação da inscrição");
  const [clientId, setClientId] = useState("");
  const [departureId, setDepartureId] = useState("");
  const [saving, setSaving] = useState(false);
  const client = clients.find((item) => item.id === clientId);
  const departure = departures.find((item) => item.id === departureId);
  const tripName = departure?.trips?.title ?? "sua viagem";
  const registrationUrl = departure?.trips?.slug ? `https://www.ekonovaadv.com.br/inscricao/${departure.trips.slug}` : "https://www.ekonovaadv.com.br/inscricao";
  const templates: Record<string, string> = {
    "Link de inscrição": "Olá, {nome}! Que bom ter você por aqui. Para se inscrever no roteiro {roteiro}, preencha sua ficha neste link: {link}",
    "Confirmação da inscrição": "Olá, {nome}! Recebemos sua inscrição para {roteiro}. A equipe Ekonova entrará em contato com os próximos passos.",
    "Documentos pendentes": "Olá, {nome}! Para concluirmos sua preparação para {roteiro}, precisamos complementar seus documentos e dados de segurança. Você consegue nos enviar por aqui?",
    "Pagamento e parcelas": "Olá, {nome}! Tudo bem? Passando para acompanharmos o planejamento do pagamento da sua viagem {roteiro}. Posso ajudar com alguma dúvida?",
    "Briefing da viagem": "Olá, {nome}! Em breve enviaremos os detalhes do briefing de {roteiro}. Será um momento para tirar dúvidas e preparar a viagem."
  };
  const [message, setMessage] = useState("");
  const templateMessage = templates[selected].replaceAll("{nome}", client?.full_name || "[nome]").replaceAll("{roteiro}", tripName).replaceAll("{link}", registrationUrl);
  useEffect(() => { setMessage(templateMessage); }, [selected, clientId, departureId, tripName, registrationUrl]);
  async function openWhatsApp() {
    if (!client) { onAction("Selecione um viajante antes de abrir a mensagem."); return; }
    if (!client.phone) { onAction("Este viajante não possui telefone cadastrado."); return; }
    setSaving(true);
    try {
      await createContactLog({ client_id: client.id, channel: "whatsapp", template_name: `${selected} · ${tripName}`, message });
      await onLogged();
      const phone = client.phone.replace(/\D/g, "");
      window.open(`https://wa.me/${phone.startsWith("55") ? phone : `55${phone}`}?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer");
      onAction("Contato registrado e mensagem preparada no WhatsApp.");
    } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível registrar o contato."); } finally { setSaving(false); }
  }
  return <section className="module-page"><p className="module-eyebrow">WhatsApp e relacionamento</p><h1>Conversas que aproximam</h1><p className="module-summary">Escolha o roteiro, o viajante e uma mensagem. Você pode ajustar o texto antes de abrir o WhatsApp; a abertura fica registrada no histórico.</p><section className="communication-layout"><div className="template-list">{Object.keys(templates).map((name) => <button key={name} className={selected === name ? "selected" : ""} onClick={() => setSelected(name)}><strong>{name}</strong><small>WhatsApp · texto editável</small></button>)}</div><article className="message-preview"><span>Preparar mensagem</span><div className="communication-selects"><label className="communication-client">Roteiro<select value={departureId} onChange={(event) => setDepartureId(event.target.value)}><option value="">Selecione um roteiro</option>{departures.map((item) => <option key={item.id} value={item.id}>{item.trips?.title}</option>)}</select></label><label className="communication-client">Viajante<select value={clientId} onChange={(event) => setClientId(event.target.value)}><option value="">Selecione um viajante</option>{clients.map((item) => <option key={item.id} value={item.id}>{item.full_name}</option>)}</select></label></div><label className="message-editor">Mensagem<textarea value={message} onChange={(event) => setMessage(event.target.value)} rows={7} /></label><small>{clients.length ? "Revise a mensagem antes de abrir o WhatsApp. Nenhum envio é automático." : "As opções de contato aparecerão quando chegarem inscrições reais."}</small><button disabled={saving || !clients.length || !departure || !message.trim()} onClick={openWhatsApp}><MessageCircle aria-hidden="true" />{saving ? "Registrando…" : "Abrir no WhatsApp e registrar"}</button></article></section><section className="module-workspace"><div><h2>Histórico de contatos</h2><p>{logs.length ? "Últimas conversas abertas pela equipe." : "Nenhum contato registrado ainda."}</p></div></section>{logs.length > 0 && <div className="clients-list contact-list">{logs.map((log) => <article key={log.id}><span>W</span><div><strong>{log.clients?.full_name ?? "Viajante"} · {log.template_name}</strong><small>{new Date(log.created_at).toLocaleString("pt-BR")}</small></div></article>)}</div>}</section>;
}

function OperationsModule({ departures, selectedDepartureId, onSelectDeparture, costs, onAction, onUpdated, onSettingsUpdated }: { departures: DepartureRecord[]; selectedDepartureId: string | null; onSelectDeparture: (id: string) => void; costs: DepartureCostRecord[]; onAction: (message: string) => void; onUpdated: (departureId: string) => Promise<void>; onSettingsUpdated: () => Promise<void> }) {
  const departure = departures.find((item) => item.id === selectedDepartureId) ?? departures[0] ?? null;
  const [saving, setSaving] = useState(false);
  const [showPricing, setShowPricing] = useState(false);
  const [capacityInput, setCapacityInput] = useState(String(departure?.capacity ?? 12));
  const [actuals, setActuals] = useState<Record<string, { quantity: string; unit: string }>>({});
  const [settings, setSettings] = useState({ currency: departure?.cost_reporting_currency ?? "BRL", exchangeRate: String(departure?.cost_exchange_rate ?? 1), profit: ((departure?.target_profit_cents ?? 0) / 100).toFixed(2).replace(".", ","), margin: String(departure?.target_margin_percent ?? 0) });
  const [selectedCostDate, setSelectedCostDate] = useState(departure?.starts_on ?? "");
  const [draft, setDraft] = useState({ costOn: departure?.starts_on ?? "", category: "Hospedagem", description: "", supplier: "", basis: "por_viajante" as "por_viajante" | "grupo", quantity: "1", unit: "", currency: departure?.cost_reporting_currency ?? "BRL" });
  useEffect(() => { setSettings({ currency: departure?.cost_reporting_currency ?? "BRL", exchangeRate: String(departure?.cost_exchange_rate ?? 1), profit: ((departure?.target_profit_cents ?? 0) / 100).toFixed(2).replace(".", ","), margin: String(departure?.target_margin_percent ?? 0) }); setCapacityInput(String(departure?.capacity ?? 12)); setSelectedCostDate(departure?.starts_on ?? ""); setDraft((current) => ({ ...current, costOn: departure?.starts_on ?? "", currency: departure?.cost_reporting_currency ?? "BRL" })); setActuals({}); }, [departure?.id, departure?.starts_on, departure?.capacity, departure?.cost_reporting_currency, departure?.cost_exchange_rate, departure?.target_profit_cents, departure?.target_margin_percent]);
  const parse = (value: string) => Math.round(Number(value.trim().includes(",") ? value.trim().replace(/\./g, "").replace(",", ".") : value) * 100);
  const money = (value: number, currency: "USD" | "BRL") => new Intl.NumberFormat(currency === "BRL" ? "pt-BR" : "en-US", { style: "currency", currency }).format(value / 100);
  const reportCurrency = (settings.currency === "USD" ? "USD" : "BRL") as "USD" | "BRL";
  const rate = Number(settings.exchangeRate.replace(",", ".")) || 1;
  const convert = (cents: number, from: "USD" | "BRL") => from === reportCurrency ? cents : from === "BRL" ? cents / rate : cents * rate;
  const costValue = (item: DepartureCostRecord, realized = false) => { const quantity = realized ? item.actual_quantity : item.planned_quantity; const unit = realized ? item.actual_unit_cents : item.planned_unit_cents; if (quantity === null || unit === null) return null; const multiplier = item.cost_basis === "por_viajante" ? departure?.capacity ?? 0 : 1; return convert(Number(quantity) * unit * multiplier, item.currency); };
  const planned = costs.reduce((sum, item) => sum + (costValue(item) ?? 0), 0);
  const realized = costs.reduce((sum, item) => sum + (costValue(item, true) ?? 0), 0);
  const price = departure ? convert(departure.price_cents, departure.currency) : 0;
  const revenue = price * (departure?.capacity ?? 0);
  const variablePerTraveler = costs.filter((item) => item.cost_basis === "por_viajante").reduce((sum, item) => sum + convert(Number(item.planned_quantity) * item.planned_unit_cents, item.currency), 0);
  const fixedTotal = costs.filter((item) => item.cost_basis === "grupo").reduce((sum, item) => sum + convert(Number(item.planned_quantity) * item.planned_unit_cents, item.currency), 0);
  const margin = revenue > 0 ? ((revenue - planned) / revenue) * 100 : 0;
  const costPerTraveler = departure?.capacity ? planned / departure.capacity : 0;
  const targetProfit = parse(settings.profit);
  const suggested = Number.isFinite(targetProfit) ? costPerTraveler + targetProfit : costPerTraveler;
  const cashPrice = departure ? departure.price_cents * (1 - (departure.cash_discount_percent ?? 0) / 100) : 0;
  const operationDays = departure ? Array.from({ length: Math.max(1, Math.round((new Date(`${departure.ends_on}T12:00:00`).getTime() - new Date(`${departure.starts_on}T12:00:00`).getTime()) / 86_400_000) + 1) }, (_, index) => { const day = new Date(`${departure.starts_on}T12:00:00`); day.setDate(day.getDate() + index); return day.toISOString().slice(0, 10); }) : [];
  const selectedDayCosts = costs.filter((item) => item.cost_on === selectedCostDate);
  const dayLabel = (date: string, index = operationDays.indexOf(date)) => `Dia ${index + 1} · ${new Date(`${date}T12:00:00`).toLocaleDateString("pt-BR", { day: "2-digit", month: "short" })}`;
  const selectedDayPlanned = selectedDayCosts.reduce((sum, item) => sum + (costValue(item) ?? 0), 0);
  const calendarCells: (string | null)[] = [...Array(new Date(`${departure.starts_on}T12:00:00`).getDay()).fill(null), ...operationDays];
  const plannedForDay = (date: string) => costs.filter((item) => item.cost_on === date).reduce((sum, item) => sum + (costValue(item) ?? 0), 0);
  async function saveSettings() { if (!departure) return; const exchangeRate = Number(settings.exchangeRate.replace(",", ".")); const targetProfit = parse(settings.profit); const targetMargin = Number(settings.margin.replace(",", ".")); if (!Number.isFinite(exchangeRate) || exchangeRate <= 0 || !Number.isFinite(targetProfit) || targetProfit < 0 || !Number.isFinite(targetMargin) || targetMargin < 0 || targetMargin >= 100) { onAction("Informe câmbio, lucro e margem válidos."); return; } setSaving(true); try { await updateDepartureCostSettings(departure.id, { cost_reporting_currency: reportCurrency, cost_exchange_rate: exchangeRate, target_margin_percent: targetMargin, target_profit_cents: targetProfit }); await onSettingsUpdated(); onAction("Definições de precificação atualizadas."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível salvar as definições."); } finally { setSaving(false); } }
  async function saveCapacity() { if (!departure) return; const capacity = Number(capacityInput); if (!Number.isInteger(capacity) || capacity < 1 || capacity > 100) { onAction("Informe uma quantidade de participantes válida."); return; } setSaving(true); try { await updateDepartureCapacity(departure.id, capacity); await onSettingsUpdated(); onAction("Quantidade de participantes atualizada."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível atualizar as vagas."); } finally { setSaving(false); } }
  async function addCost(event: React.FormEvent) { event.preventDefault(); if (!departure) return; const quantity = Number(draft.quantity.replace(",", ".")); const unit = parse(draft.unit); if (!draft.costOn || !Number.isFinite(quantity) || quantity < 0 || !Number.isFinite(unit) || unit < 0) { onAction("Informe fornecedor, quantidade e valor válidos."); return; } setSaving(true); try { await createDepartureCost({ departure_id: departure.id, cost_on: draft.costOn, category: draft.category, description: draft.description.trim() || draft.category, supplier: draft.supplier.trim() || null, cost_basis: draft.basis, planned_quantity: quantity, planned_unit_cents: unit, currency: draft.currency as "USD" | "BRL", notes: null }); await onUpdated(departure.id); setDraft({ costOn: selectedCostDate, category: "Hospedagem", description: "", supplier: "", basis: "por_viajante", quantity: "1", unit: "", currency: reportCurrency }); onAction("Despesa registrada."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível adicionar a despesa."); } finally { setSaving(false); } }
  async function saveActual(item: DepartureCostRecord) { const form = actuals[item.id] ?? { quantity: item.actual_quantity?.toString() ?? item.planned_quantity.toString(), unit: item.actual_unit_cents ? (item.actual_unit_cents / 100).toFixed(2) : "" }; const quantity = Number(form.quantity.replace(",", ".")); const unit = parse(form.unit); if (!Number.isFinite(quantity) || quantity < 0 || !Number.isFinite(unit) || unit < 0) { onAction("Informe quantidade e custo realizado válidos."); return; } setSaving(true); try { await updateDepartureCostActual(item.id, { actual_quantity: quantity, actual_unit_cents: unit }); if (departure) await onUpdated(departure.id); onAction("Custo realizado registrado."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível registrar o custo realizado."); } finally { setSaving(false); } }
  if (!departure) return <section className="empty-section"><h2>Nenhuma saída cadastrada</h2><p>Crie uma saída antes de formar o preço.</p></section>;
  if (showPricing) return <section className="module-page operations-page"><p className="module-eyebrow">Resumo e formação de preço</p><h1>{departure.trips?.title}</h1><p className="module-summary">Ajuste as vagas e o lucro até chegar ao preço de venda que você deseja.</p><button className="operations-back" onClick={() => setShowPricing(false)}>← Voltar às despesas</button><section className="pricing-controls"><label>Participantes planejados<input inputMode="numeric" value={capacityInput} onChange={(event) => setCapacityInput(event.target.value)} /><button onClick={saveCapacity} disabled={saving}>Atualizar vagas</button></label><label>Lucro desejado por pessoa<input inputMode="decimal" value={settings.profit} onChange={(event) => setSettings((current) => ({ ...current, profit: event.target.value }))} /><button onClick={saveSettings} disabled={saving}>Atualizar lucro</button></label></section><section className="operations-summary"><article><span>Total das despesas</span><strong>{money(planned, reportCurrency)}</strong><small>{costs.length} lançamentos</small></article><article><span>Custo por participante</span><strong>{money(costPerTraveler, reportCurrency)}</strong><small>considerando {departure.capacity} participantes</small></article><article><span>Lucro por participante</span><strong>{money(targetProfit, reportCurrency)}</strong><small>definido pela equipe</small></article><article><span>Preço sugerido</span><strong>{money(suggested, reportCurrency)}</strong><small>custo por pessoa + lucro</small></article></section><section className="pricing-commercial"><div><strong>Preço comercial atual</strong><b>{money(departure.price_cents, departure.currency)}</b><small>À vista: {money(cashPrice, departure.currency)}</small></div><p>Se quiser, ajuste o lucro e a quantidade de participantes. O preço sugerido muda na hora para apoiar sua decisão.</p></section></section>;
  return (
    <section className="module-page operations-page">
      <p className="module-eyebrow">Operações e precificação</p>
      <h1>Custos por roteiro</h1>
      <p className="module-summary">A formação de preço segue a lógica da planilha: despesas por viajante, despesas do grupo divididas pelas vagas, lucro desejado e preço comercial separado.</p>

      <section className="operations-selector">
        <label>Roteiro<select value={departure.id} onChange={(event) => onSelectDeparture(event.target.value)}>{departures.map((item) => <option key={item.id} value={item.id}>{item.trips?.title} · {new Date(`${item.starts_on}T12:00:00`).toLocaleDateString("pt-BR")}</option>)}</select></label>
        <button type="button" onClick={() => setShowPricing(true)}>Ver resumo e formar preço</button>
      </section>

      <form className="quick-cost-form" onSubmit={addCost}>
        <div><span>Registrar despesa · {dayLabel(selectedCostDate)}</span><strong>Escolha o tipo e informe somente o fornecedor e o valor.</strong></div>
        <label>Despesa<select value={draft.category} onChange={(event) => setDraft((current) => ({ ...current, category: event.target.value }))}>{["Hospedagem", "Transporte", "Alimentação", "Passeios", "Equipe", "Materiais", "Seguro", "Outros"].map((category) => <option key={category}>{category}</option>)}</select></label>
        <label>Fornecedor<input value={draft.supplier} onChange={(event) => setDraft((current) => ({ ...current, supplier: event.target.value }))} placeholder="Nome do fornecedor" required /></label>
        <label>Valor<input inputMode="decimal" value={draft.unit} onChange={(event) => setDraft((current) => ({ ...current, unit: event.target.value }))} placeholder="0,00" required /></label>
        <label>Como calcular<select value={draft.basis} onChange={(event) => setDraft((current) => ({ ...current, basis: event.target.value as "por_viajante" | "grupo" }))}><option value="por_viajante">Por participante</option><option value="grupo">Custo do grupo</option></select></label>
        <button disabled={saving}>{saving ? "Registrando…" : "Registrar despesa"}</button>
      </form>

      <section className="operations-summary">
        <article><span>Custo por viajante</span><strong>{money(costPerTraveler, reportCurrency)}</strong><small>{money(variablePerTraveler, reportCurrency)} individual + {money(departure.capacity ? fixedTotal / departure.capacity : 0, reportCurrency)} do grupo</small></article>
        <article><span>Lucro desejado</span><strong>{money(targetProfit, reportCurrency)}</strong><small>por viajante</small></article>
        <article><span>Venda sugerida</span><strong>{money(suggested, reportCurrency)}</strong><small>custo + lucro desejado</small></article>
        <article><span>Preço comercial</span><strong>{money(departure.price_cents, departure.currency)}</strong><small>À vista: {money(cashPrice, departure.currency)} · desconto de {departure.cash_discount_percent}%</small></article>
      </section>

      <details className="operations-settings">
        <summary>Configurações de câmbio e moeda</summary>
        <div><strong>Premissas de precificação</strong><small>Os custos podem ser lançados em BRL ou USD. O câmbio consolida tudo na moeda de análise.</small></div>
        <label>Moeda de análise<select value={settings.currency} onChange={(event) => setSettings((current) => ({ ...current, currency: event.target.value as "USD" | "BRL" }))}><option value="BRL">BRL</option><option value="USD">USD</option></select></label>
        <label>Câmbio BRL por USD<input inputMode="decimal" value={settings.exchangeRate} onChange={(event) => setSettings((current) => ({ ...current, exchangeRate: event.target.value }))} /></label>
        <label>Lucro desejado por viajante<input inputMode="decimal" value={settings.profit} onChange={(event) => setSettings((current) => ({ ...current, profit: event.target.value }))} /></label>
        <button onClick={saveSettings} disabled={saving}>{saving ? "Salvando…" : "Salvar premissas"}</button>
      </details>

      <section className="operations-costs">
        <header><div><h2>Planilha operacional por dia</h2><p>Escolha um dia da viagem e registre as despesas, como na sua planilha atual.</p></div><strong>Total previsto: {money(planned, reportCurrency)}</strong></header>
        <div className="operation-calendar" aria-label="Calendário de despesas">{calendarCells.map((date, index) => date ? <button type="button" key={date} className={selectedCostDate === date ? "selected" : ""} onClick={() => { setSelectedCostDate(date); setDraft((current) => ({ ...current, costOn: date })); }}><b>{dayLabel(date)}</b><small>{costs.filter((item) => item.cost_on === date).length ? `${costs.filter((item) => item.cost_on === date).length} despesa(s)` : "Sem lançamentos"}</small><em>{plannedForDay(date) ? money(plannedForDay(date), reportCurrency) : "Adicionar"}</em></button> : <i key={`blank-${index}`} aria-hidden="true" />)}</div>
        <div className="operation-day-heading"><div><span>{dayLabel(selectedCostDate)}</span><strong>{selectedDayCosts.length} despesa(s) lançada(s)</strong></div><b>Previsto do dia: {money(selectedDayPlanned, reportCurrency)}</b></div>
        {selectedDayCosts.length ? <div className="operations-table"><div className="operations-head"><span>Despesa</span><span>Base</span><span>Previsto</span><span>Realizado</span></div>{selectedDayCosts.map((item) => { const current = actuals[item.id] ?? { quantity: item.actual_quantity?.toString() ?? item.planned_quantity.toString(), unit: item.actual_unit_cents ? (item.actual_unit_cents / 100).toFixed(2).replace(".", ",") : "" }; return <article key={item.id}><div><strong>{item.description}</strong><small>{item.category}{item.supplier ? ` · ${item.supplier}` : ""}</small></div><div><b>{item.cost_basis === "por_viajante" ? "Por viajante" : "Grupo"}</b><small>{item.planned_quantity} × {money(item.planned_unit_cents, item.currency)}</small></div><div><b>{money(costValue(item) ?? 0, reportCurrency)}</b><small>{item.currency}</small></div><form onSubmit={(event) => { event.preventDefault(); void saveActual(item); }}><input aria-label={`Quantidade realizada de ${item.description}`} value={current.quantity} onChange={(event) => setActuals((all) => ({ ...all, [item.id]: { ...current, quantity: event.target.value } }))} placeholder="Qtd." /><input aria-label={`Custo realizado de ${item.description}`} value={current.unit} onChange={(event) => setActuals((all) => ({ ...all, [item.id]: { ...current, unit: event.target.value } }))} placeholder="Custo" /><button disabled={saving}>{item.actual_unit_cents !== null ? "Atualizar" : "Registrar"}</button></form></article>; })}</div> : <div className="empty-records"><strong>Nenhuma despesa neste dia.</strong><p>Use o formulário abaixo para lançar hospedagem, transporte, alimentação, guia ou qualquer outro custo.</p></div>}
      </section>

      <form className="operations-add-cost" onSubmit={addCost}>
        <h2>Adicionar despesa em {dayLabel(draft.costOn)}</h2>
        <label>Dia<input type="date" min={departure.starts_on} max={departure.ends_on} value={draft.costOn} onChange={(event) => { setDraft((current) => ({ ...current, costOn: event.target.value })); setSelectedCostDate(event.target.value); }} required /></label>
        <label>Categoria<select value={draft.category} onChange={(event) => setDraft((current) => ({ ...current, category: event.target.value }))}>{["Hospedagem", "Transporte", "Alimentação", "Passeios", "Equipe", "Materiais", "Seguro", "Outros"].map((category) => <option key={category}>{category}</option>)}</select></label>
        <label>Descrição<input value={draft.description} onChange={(event) => setDraft((current) => ({ ...current, description: event.target.value }))} placeholder="Ex.: Hotel em San Pedro" required /></label>
        <label>Fornecedor<input value={draft.supplier} onChange={(event) => setDraft((current) => ({ ...current, supplier: event.target.value }))} placeholder="Opcional" /></label>
        <label>Tipo<select value={draft.basis} onChange={(event) => setDraft((current) => ({ ...current, basis: event.target.value as "por_viajante" | "grupo" }))}><option value="por_viajante">Por viajante</option><option value="grupo">Custo do grupo</option></select></label>
        <label>Quantidade<input inputMode="decimal" value={draft.quantity} onChange={(event) => setDraft((current) => ({ ...current, quantity: event.target.value }))} required /></label>
        <label>Valor unitário<input inputMode="decimal" value={draft.unit} onChange={(event) => setDraft((current) => ({ ...current, unit: event.target.value }))} placeholder="0,00" required /></label>
        <label>Moeda<select value={draft.currency} onChange={(event) => setDraft((current) => ({ ...current, currency: event.target.value as "USD" | "BRL" }))}><option value="BRL">BRL</option><option value="USD">USD</option></select></label>
        <button disabled={saving}>{saving ? "Adicionando…" : "Adicionar despesa"}</button>
      </form>
    </section>
  );
  return <section className="module-page operations-page"><p className="module-eyebrow">Operações e precificação</p><h1>Custos por roteiro</h1><p className="module-summary">Monte o custo da saída, acompanhe o realizado e forme o preço de venda com segurança.</p><section className="operations-selector"><label>Roteiro<select value={departure.id} onChange={(event) => onSelectDeparture(event.target.value)}>{departures.map((item) => <option key={item.id} value={item.id}>{item.trips?.title} · {new Date(`${item.starts_on}T12:00:00`).toLocaleDateString("pt-BR")}</option>)}</select></label><span>{departure.capacity} vagas planejadas</span></section><section className="operations-summary"><article><span>Custo previsto</span><strong>{money(planned, reportCurrency)}</strong><small>{money(departure.capacity ? planned / departure.capacity : 0, reportCurrency)} por vaga</small></article><article><span>Custo realizado</span><strong>{realized ? money(realized, reportCurrency) : "A registrar"}</strong><small>{realized ? `${Math.round((realized / planned) * 100)}% do previsto` : "Sem despesas realizadas"}</small></article><article><span>Preço de venda atual</span><strong>{money(price, reportCurrency)}</strong><small>por vaga · {money(revenue, reportCurrency)} no grupo</small></article><article><span>Margem prevista</span><strong>{margin.toFixed(1).replace(".", ",")}%</strong><small>Preço sugerido: {money(suggested, reportCurrency)}</small></article></section><section className="operations-settings"><div><strong>Premissas de precificação</strong><small>Use o câmbio para consolidar custos em uma única moeda. Os custos continuam registrados na moeda de origem.</small></div><label>Moeda de análise<select value={settings.currency} onChange={(event) => setSettings((current) => ({ ...current, currency: event.target.value as "USD" | "BRL" }))}><option value="BRL">BRL</option><option value="USD">USD</option></select></label><label>Câmbio BRL por USD<input inputMode="decimal" value={settings.exchangeRate} onChange={(event) => setSettings((current) => ({ ...current, exchangeRate: event.target.value }))} /></label><label>Margem desejada (%)<input inputMode="decimal" value={settings.margin} onChange={(event) => setSettings((current) => ({ ...current, margin: event.target.value }))} /></label><button onClick={saveSettings} disabled={saving}>{saving ? "Salvando…" : "Salvar premissas"}</button></section><section className="operations-costs"><header><div><h2>Despesas previstas</h2><p>Custos por viajante aumentam conforme o grupo. Custos de grupo são distribuídos entre as vagas.</p></div></header>{costs.length ? <div className="operations-table"><div className="operations-head"><span>Despesa</span><span>Base</span><span>Previsto</span><span>Realizado</span></div>{costs.map((item) => { const current = actuals[item.id] ?? { quantity: item.actual_quantity?.toString() ?? item.planned_quantity.toString(), unit: item.actual_unit_cents ? (item.actual_unit_cents / 100).toFixed(2).replace(".", ",") : "" }; return <article key={item.id}><div><strong>{item.description}</strong><small>{item.category}{item.supplier ? ` · ${item.supplier}` : ""}</small></div><div><b>{item.cost_basis === "por_viajante" ? "Por viajante" : "Grupo"}</b><small>{item.planned_quantity} × {money(item.planned_unit_cents, item.currency)}</small></div><div><b>{money(costValue(item) ?? 0, reportCurrency)}</b><small>{item.currency}</small></div><form onSubmit={(event) => { event.preventDefault(); void saveActual(item); }}><input aria-label={`Quantidade realizada de ${item.description}`} value={current.quantity} onChange={(event) => setActuals((all) => ({ ...all, [item.id]: { ...current, quantity: event.target.value } }))} placeholder="Qtd." /><input aria-label={`Custo realizado de ${item.description}`} value={current.unit} onChange={(event) => setActuals((all) => ({ ...all, [item.id]: { ...current, unit: event.target.value } }))} placeholder="Custo" /><button disabled={saving}>{item.actual_unit_cents !== null ? "Atualizar" : "Registrar"}</button></form></article>; })}</div> : <div className="empty-records"><strong>Nenhuma despesa planejada ainda.</strong><p>Adicione a primeira despesa abaixo para começar a formar o preço.</p></div>}</section><form className="operations-add-cost" onSubmit={addCost}><h2>Adicionar despesa prevista</h2><label>Categoria<select value={draft.category} onChange={(event) => setDraft((current) => ({ ...current, category: event.target.value }))}>{["Hospedagem", "Transporte", "Alimentação", "Passeios", "Equipe", "Materiais", "Seguro", "Outros"].map((category) => <option key={category}>{category}</option>)}</select></label><label>Descrição<input value={draft.description} onChange={(event) => setDraft((current) => ({ ...current, description: event.target.value }))} placeholder="Ex.: Hotel em San Pedro" required /></label><label>Fornecedor<input value={draft.supplier} onChange={(event) => setDraft((current) => ({ ...current, supplier: event.target.value }))} placeholder="Opcional" /></label><label>Tipo<select value={draft.basis} onChange={(event) => setDraft((current) => ({ ...current, basis: event.target.value as "por_viajante" | "grupo" }))}><option value="por_viajante">Por viajante</option><option value="grupo">Custo do grupo</option></select></label><label>Quantidade<input inputMode="decimal" value={draft.quantity} onChange={(event) => setDraft((current) => ({ ...current, quantity: event.target.value }))} required /></label><label>Valor unitário<input inputMode="decimal" value={draft.unit} onChange={(event) => setDraft((current) => ({ ...current, unit: event.target.value }))} placeholder="0,00" required /></label><label>Moeda<select value={draft.currency} onChange={(event) => setDraft((current) => ({ ...current, currency: event.target.value as "USD" | "BRL" }))}><option value="BRL">BRL</option><option value="USD">USD</option></select></label><button disabled={saving}>{saving ? "Adicionando…" : "Adicionar despesa"}</button></form></section>;
}

function ReportsModule({ clients, payments }: { clients: ClientRecord[]; payments: PaymentRecord[] }) {
  const total = payments.reduce((sum, item) => sum + item.amount_cents, 0);
  const received = payments.filter((item) => item.status === "pago").reduce((sum, item) => sum + item.amount_cents, 0);
  const open = total - received;
  const travelers = new Set(payments.map((item) => item.reservations?.clients?.full_name).filter(Boolean)).size;
  const openInstallments = payments.filter((item) => item.status !== "pago").sort((a, b) => a.due_on.localeCompare(b.due_on));
  const money = (value: number) => new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(value / 100);
  return <section className="module-page"><p className="module-eyebrow">Leitura do negócio</p><h1>Relatórios de jornadas</h1><p className="module-summary">Visão atualizada de inscrições, ocupação e fluxo financeiro do Andes Essencial.</p><div className="module-grid report-grid"><article><span>Clientes cadastrados</span><strong>{clients.length}</strong><small>Fichas disponíveis na gestão</small></article><article><span>Viajantes com reserva</span><strong>{travelers}</strong><small>Inscrições recebidas para a saída</small></article><article><span>Receita prevista</span><strong>{money(total)}</strong><small>Somatório das entradas e parcelas</small></article><article><span>Recebido</span><strong>{money(received)}</strong><small>Pagamentos marcados como pagos</small></article><article><span>Em aberto</span><strong>{money(open)}</strong><small>{openInstallments.length} cobrança(s) pendente(s)</small></article><article><span>Próximo vencimento</span><strong>{openInstallments[0] ? new Date(`${openInstallments[0].due_on}T12:00:00`).toLocaleDateString("pt-BR") : "Sem pendências"}</strong><small>{openInstallments[0]?.reservations?.clients?.full_name ?? "Tudo regular"}</small></article></div><section className="module-workspace report-workspace"><div><h2>Parcelas em acompanhamento</h2><p>{openInstallments.length ? "Use esta lista para priorizar os próximos contatos da equipe." : "Não há pagamentos pendentes registrados."}</p></div></section>{openInstallments.length > 0 && <div className="clients-list financial-list">{openInstallments.slice(0, 8).map((payment) => <article key={payment.id}><span>!</span><div><strong>{payment.reservations?.clients?.full_name ?? "Cliente"}</strong><small>Vencimento: {new Date(`${payment.due_on}T12:00:00`).toLocaleDateString("pt-BR")}</small></div><b>{money(payment.amount_cents)}</b></article>)}</div>}</section>;
}

function FinanceModule({ payments, departures, onAction, onUpdated }: { payments: PaymentRecord[]; departures: DepartureRecord[]; onAction: (message: string) => void; onUpdated: () => Promise<void> }) {
  const [departureId, setDepartureId] = useState("all");
  const [savingId, setSavingId] = useState<string | null>(null);
  const [openReservationId, setOpenReservationId] = useState<string | null>(null);
  const [editingReservationId, setEditingReservationId] = useState<string | null>(null);
  const [savingPlan, setSavingPlan] = useState(false);
  const [specialPlan, setSpecialPlan] = useState({ entrance: "", installments: "1", firstDueOn: new Date().toISOString().slice(0, 10) });
  const visible = departureId === "all" ? payments : payments.filter((item) => item.reservations?.departure_id === departureId);
  const currency = (item: PaymentRecord) => item.reservations?.departures?.currency ?? "USD";
  const money = (value: number, itemCurrency: "USD" | "BRL") => new Intl.NumberFormat(itemCurrency === "BRL" ? "pt-BR" : "en-US", { style: "currency", currency: itemCurrency }).format(value / 100);
  const parseAmount = (value: string) => { const typed = value.trim(); return Math.round(Number(typed.includes(",") ? typed.replace(/\./g, "").replace(",", ".") : typed) * 100); };
  const clientPayments = Array.from(visible.reduce((groups, payment) => { const group = groups.get(payment.reservation_id) ?? { id: payment.reservation_id, payments: [] as PaymentRecord[] }; group.payments.push(payment); groups.set(payment.reservation_id, group); return groups; }, new Map<string, { id: string; payments: PaymentRecord[] }>()).values());
  async function markPaid(payment: PaymentRecord) { setSavingId(payment.id); try { await markPaymentAsPaid(payment.id); await onUpdated(); onAction("Pagamento confirmado e registrado no financeiro."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível confirmar o pagamento."); } finally { setSavingId(null); } }
  function openCondition(group: { id: string; payments: PaymentRecord[] }) { const planned = group.payments.reduce((sum, item) => sum + item.amount_cents, 0); const firstPending = group.payments.filter((item) => item.status !== "pago").sort((a, b) => a.due_on.localeCompare(b.due_on))[0]; setEditingReservationId(group.id); setSpecialPlan({ entrance: (planned / 100).toFixed(2).replace(".", ","), installments: "0", firstDueOn: firstPending?.due_on ?? new Date().toISOString().slice(0, 10) }); }
  async function saveCondition(group: { id: string; payments: PaymentRecord[] }, itemCurrency: "USD" | "BRL") { const totalCents = group.payments.reduce((sum, item) => sum + item.amount_cents, 0); const entranceCents = parseAmount(specialPlan.entrance); const installments = Number(specialPlan.installments); if (!Number.isFinite(entranceCents) || entranceCents < 0 || entranceCents > totalCents || !Number.isInteger(installments)) { onAction("Informe uma entrada e parcelas válidas."); return; } setSavingPlan(true); try { await replacePendingPaymentPlan({ reservationId: group.id, totalCents, entranceCents, installments, firstDueOn: specialPlan.firstDueOn, currency: itemCurrency }); await onUpdated(); setEditingReservationId(null); onAction("Condição especial aplicada somente a este cliente."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível aplicar a condição especial."); } finally { setSavingPlan(false); } }
  return <section className="module-page"><p className="module-eyebrow">Financeiro operacional</p><h1>Pagamentos por cliente</h1><p className="module-summary">Abra um viajante para acompanhar suas parcelas e, se necessário, criar uma condição especial apenas para aquele cadastro.</p><section className="finance-filter"><label>Saída<select value={departureId} onChange={(event) => { setDepartureId(event.target.value); setOpenReservationId(null); setEditingReservationId(null); }}><option value="all">Todas as saídas</option>{departures.map((departure) => <option key={departure.id} value={departure.id}>{departure.trips?.title} · {departure.currency}</option>)}</select></label><span>{clientPayments.length} cliente(s) com pagamento</span></section>{!clientPayments.length ? <section className="empty-section"><h2>Sem pagamentos registrados</h2><p>As opções de pagamento aparecerão aqui quando uma inscrição for concluída.</p></section> : <section className="finance-clients">{clientPayments.map((group) => { const first = group.payments[0]; const itemCurrency = currency(first); const pending = group.payments.filter((item) => item.status !== "pago"); const planned = group.payments.reduce((sum, item) => sum + item.amount_cents, 0); const received = group.payments.filter((item) => item.status === "pago").reduce((sum, item) => sum + item.amount_cents, 0); const open = openReservationId === group.id; const editing = editingReservationId === group.id; const hasPaid = group.payments.some((item) => item.status === "pago"); const entrance = parseAmount(specialPlan.entrance); const remaining = Number.isFinite(entrance) ? Math.max(0, planned - entrance) : planned; return <article key={group.id} className={open ? "open" : ""}><button className="finance-client-summary" onClick={() => { setOpenReservationId(open ? null : group.id); if (open) setEditingReservationId(null); }} aria-expanded={open}><span>{open ? "−" : "+"}</span><div><strong>{first.reservations?.clients?.full_name ?? "Cliente"}</strong><small>{first.reservations?.departures?.trips?.title ?? "Saída"} · {group.payments.length} lançamento(s)</small></div><div className="finance-client-total"><small>{pending.length ? `${pending.length} em aberto` : "Tudo pago"}</small><b>{money(planned - received, itemCurrency)}</b></div><em>{open ? "Fechar" : "Ver financeiro"}</em></button>{open && <div className="finance-client-details"><header><div><strong>Plano contratado</strong><small>Previsto: {money(planned, itemCurrency)} · Recebido: {money(received, itemCurrency)}</small></div>{!hasPaid && <button className="finance-condition-toggle" onClick={() => editing ? setEditingReservationId(null) : openCondition(group)}>{editing ? "Cancelar" : "Condição especial"}</button>}</header>{hasPaid ? <p className="finance-condition-note">Há pagamento confirmado. Para preservar o histórico, esta condição não pode mais ser alterada.</p> : editing && <form className="finance-condition" onSubmit={(event) => { event.preventDefault(); void saveCondition(group, itemCurrency); }}><div><strong>Condição especial deste cliente</strong><small>O valor total contratado permanece {money(planned, itemCurrency)}. Isso não altera o padrão do roteiro.</small></div><label>Entrada<input inputMode="decimal" value={specialPlan.entrance} onChange={(event) => setSpecialPlan((current) => ({ ...current, entrance: event.target.value }))} placeholder="Ex.: 500,00" required /></label><label>Parcelas do saldo<select value={specialPlan.installments} onChange={(event) => setSpecialPlan((current) => ({ ...current, installments: event.target.value }))}>{Array.from({ length: 13 }, (_, value) => <option key={value} value={value}>{value === 0 ? "Sem parcelas" : `${value}x`}</option>)}</select></label><label>Primeiro vencimento<input type="date" value={specialPlan.firstDueOn} onChange={(event) => setSpecialPlan((current) => ({ ...current, firstDueOn: event.target.value }))} required /></label><p>Saldo a parcelar: <b>{money(remaining, itemCurrency)}</b>. As parcelas seguintes vencem mensalmente.</p><button type="submit" disabled={savingPlan}>{savingPlan ? "Salvando…" : "Aplicar condição especial"}</button></form>}{group.payments.sort((a, b) => a.due_on.localeCompare(b.due_on)).map((payment) => { const due = new Date(`${payment.due_on}T12:00:00`).toLocaleDateString("pt-BR"); return <div className="finance-installment" key={payment.id}><span className={payment.status === "pago" ? "paid" : "pending"}>{payment.status === "pago" ? "✓" : "!"}</span><div><strong>{payment.reference ?? "Pagamento"}</strong><small>{payment.status === "pago" ? `Pago em ${payment.paid_on ? new Date(`${payment.paid_on}T12:00:00`).toLocaleDateString("pt-BR") : "data não informada"}` : `Vencimento: ${due}`}</small></div><b>{money(payment.amount_cents, itemCurrency)}</b>{payment.status === "pago" ? <em>Confirmado</em> : <button disabled={savingId === payment.id} onClick={() => markPaid(payment)}>{savingId === payment.id ? "Confirmando…" : "Confirmar pagamento"}</button>}</div>; })}</div>}</article>; })}</section>}</section>;
}

function FinanceModuleLegacy({ payments, departures, onAction, onUpdated }: { payments: PaymentRecord[]; departures: DepartureRecord[]; onAction: (message: string) => void; onUpdated: () => Promise<void> }) {
  const [departureId, setDepartureId] = useState("all");
  const [savingId, setSavingId] = useState<string | null>(null);
  const [openReservationId, setOpenReservationId] = useState<string | null>(null);
  const visible = departureId === "all" ? payments : payments.filter((item) => item.reservations?.departure_id === departureId);
  const currency = (item: PaymentRecord) => item.reservations?.departures?.currency ?? "USD";
  const money = (value: number, itemCurrency: "USD" | "BRL") => new Intl.NumberFormat(itemCurrency === "BRL" ? "pt-BR" : "en-US", { style: "currency", currency: itemCurrency }).format(value / 100);
  const clientPayments = Array.from(visible.reduce((groups, payment) => {
    const reservationId = payment.reservations?.departure_id && payment.reservations?.clients?.id ? `${payment.reservations.departure_id}:${payment.reservations.clients.id}` : payment.id;
    const group = groups.get(reservationId) ?? { id: reservationId, payments: [] as PaymentRecord[] };
    group.payments.push(payment); groups.set(reservationId, group); return groups;
  }, new Map<string, { id: string; payments: PaymentRecord[] }>()).values());
  async function markPaid(payment: PaymentRecord) { setSavingId(payment.id); try { await markPaymentAsPaid(payment.id); await onUpdated(); onAction("Pagamento confirmado e registrado no financeiro."); } catch (error) { onAction(error instanceof Error ? error.message : "Não foi possível confirmar o pagamento."); } finally { setSavingId(null); } }
  return <section className="module-page"><p className="module-eyebrow">Financeiro operacional</p><h1>Pagamentos por cliente</h1><p className="module-summary">Abra um viajante para ver apenas as opções de pagamento, parcelas e confirmações daquele cadastro.</p><section className="finance-filter"><label>Saída<select value={departureId} onChange={(event) => { setDepartureId(event.target.value); setOpenReservationId(null); }}><option value="all">Todas as saídas</option>{departures.map((departure) => <option key={departure.id} value={departure.id}>{departure.trips?.title} · {departure.currency}</option>)}</select></label><span>{clientPayments.length} cliente(s) com pagamento</span></section>{!clientPayments.length ? <section className="empty-section"><h2>Sem pagamentos registrados</h2><p>As opções de pagamento aparecerão aqui quando uma inscrição for concluída.</p></section> : <section className="finance-clients">{clientPayments.map((group) => { const first = group.payments[0]; const itemCurrency = currency(first); const pending = group.payments.filter((item) => item.status !== "pago"); const planned = group.payments.reduce((sum, item) => sum + item.amount_cents, 0); const received = group.payments.filter((item) => item.status === "pago").reduce((sum, item) => sum + item.amount_cents, 0); const open = openReservationId === group.id; return <article key={group.id} className={open ? "open" : ""}><button className="finance-client-summary" onClick={() => setOpenReservationId(open ? null : group.id)} aria-expanded={open}><span>{open ? "−" : "+"}</span><div><strong>{first.reservations?.clients?.full_name ?? "Cliente"}</strong><small>{first.reservations?.departures?.trips?.title ?? "Saída"} · {group.payments.length} opção(ões) de pagamento</small></div><div className="finance-client-total"><small>{pending.length ? `${pending.length} em aberto` : "Tudo pago"}</small><b>{money(planned - received, itemCurrency)}</b></div><em>{open ? "Fechar" : "Ver pagamentos"}</em></button>{open && <div className="finance-client-details"><header><div><strong>Opções de pagamento</strong><small>Previsto: {money(planned, itemCurrency)} · Recebido: {money(received, itemCurrency)}</small></div></header>{group.payments.sort((a, b) => a.due_on.localeCompare(b.due_on)).map((payment) => { const due = new Date(`${payment.due_on}T12:00:00`).toLocaleDateString("pt-BR"); return <div className="finance-installment" key={payment.id}><span className={payment.status === "pago" ? "paid" : "pending"}>{payment.status === "pago" ? "✓" : "!"}</span><div><strong>{payment.reference ?? "Pagamento"}</strong><small>{payment.status === "pago" ? `Pago em ${payment.paid_on ? new Date(`${payment.paid_on}T12:00:00`).toLocaleDateString("pt-BR") : "data não informada"}` : `Vencimento: ${due}`}</small></div><b>{money(payment.amount_cents, itemCurrency)}</b>{payment.status === "pago" ? <em>Confirmado</em> : <button disabled={savingId === payment.id} onClick={() => markPaid(payment)}>{savingId === payment.id ? "Confirmando…" : "Confirmar pagamento"}</button>}</div>; })}</div>}</article>; })}</section>}</section>;
}
